/* Rozwiązania krok po kroku zadań z arkuszy (na liczbach z oryginału) — z generatorów. Plik generowany. */
AQ.MATURA_SOL = {"2209-1":["Pomysł: najpierw liczymy nawias ($b^{-1}=\\frac1b$), potem wykładnik $-2$: odwracamy ułamek i podnosimy do kwadratu.","$2^{-1}=\\frac{1}{2}$, więc $3\\cdot 2^{-1}=3\\cdot\\frac{1}{2}=\\frac{3}{2}$.","W nawiasie: $1+\\frac{3}{2}=\\frac{2}{2}+\\frac{3}{2}=\\frac{5}{2}$.","Wykładnik $-2$: odwracamy ułamek i podnosimy do kwadratu: $\\left(\\frac{5}{2}\\right)^{-2}=\\left(\\frac{2}{5}\\right)^{2}=\\frac{4}{25}$.","Odpowiedź: $\\frac{4}{25}$."],"inf-1":["Pomysł: liczymy osobno każdy nawias, a dzielenie przez ułamek zamieniamy na mnożenie przez odwrotność.","Pierwszy nawias: $1-\\frac{1}{2025}=\\frac{2025}{2025}-\\frac{1}{2025}=\\frac{2024}{2025}$.","Dzielimy przez ułamek, czyli mnożymy przez odwrotność: $2024:\\frac{2024}{2025}=2024\\cdot\\frac{2025}{2024}=2025$ (2024 się skraca).","Drugi nawias: $1-\\frac{2025}{2024}=\\frac{2024}{2024}-\\frac{2025}{2024}=\\frac{2024-2025}{2024}=-\\frac{1}{2024}$.","$-\\frac{1}{2024}:\\frac{1}{2024}=-\\frac{1}{2024}\\cdot 2024=-1$.","Całość: $2025-(-1)=2025+1=2026$.","Odpowiedź: $2026$."],"2406-1":["Pomysł: potęgę o wykładniku ułamkowym liczymy w dwóch ruchach — mianownik wykładnika to stopień pierwiastka, licznik to zwykła potęga. Ujemny wykładnik oznacza odwrotność.","Wykładnik $\\frac{3}{5}$: mianownik $5$ to stopień pierwiastka, licznik $3$ to potęga. Więc $32^{\\frac{3}{5}}=\\left(\\sqrt[5]{32}\\right)^{3}$.","$\\sqrt[5]{32}=2$, bo $2\\cdot 2\\cdot 2\\cdot 2\\cdot 2=32$.","$2^{3}=2\\cdot 2\\cdot 2=8$.","$2^{-1}=\\frac{1}{2}$ (minus w wykładniku to odwrotność).","$\\frac{1}{2}\\cdot 8=\\frac{8}{2}=4$.","Odpowiedź: $4$."],"2408-2":["Pomysł: zamieniamy ułamek dziesiętny w wykładniku na zwykły ($0{,}5=\\frac12$, czyli pierwiastek kwadratowy), a minus w wykładniku odwraca ułamek.","Zamieniamy wykładnik na ułamek zwykły: $-0{,}5=-\\frac12$.","Minus w wykładniku odwraca ułamek, a $\\frac12$ w wykładniku to pierwiastek kwadratowy: $\\left(\\frac{4}{25}\\right)^{-0{,}5}=\\left(\\frac{25}{4}\\right)^{\\frac12}=\\sqrt{\\frac{25}{4}}$.","Pierwiastek z ułamka to pierwiastek z licznika przez pierwiastek z mianownika: $\\frac{\\sqrt{25}}{\\sqrt{4}}=\\frac{5}{2}=2{,}5$.","Odpowiedź: $2{,}5$."],"2608-2":["Pomysł: każdą potęgę liczymy osobno, a ujemne wykładniki zamieniamy na odwrotności — czynnik z ujemną potęgą „przechodzi” na drugą stronę kreski ułamkowej.","Liczymy każdą potęgę osobno. $4^{0{,}5}=4^{\\frac12}=\\sqrt{4}=2$.","Minus w wykładniku oznacza odwrotność: $3^{-1}=\\frac{1}{3}$, $\\ 3^{-2}=\\frac{1}{3^2}=\\frac{1}{9}$, $\\ 2^{-1}=\\frac{1}{2}$.","Licznik: $\\frac{1}{3}\\cdot 2=\\frac{2}{3}$. Mianownik: $\\frac{1}{9}\\cdot\\frac{1}{2}=\\frac{1}{9\\cdot 2}=\\frac{1}{18}$.","Dzielimy przez ułamek, czyli mnożymy przez jego odwrotność: $\\frac{2}{3}:\\frac{1}{18}=\\frac{2}{3}\\cdot 18$.","$\\frac{2\\cdot 18}{3}=\\frac{36}{3}=12$.","Odpowiedź: $12$."],"2312-1":["Pomysł: wykładniki dodajemy przy mnożeniu, a mnożymy przy potędze potęgi.","Zamieniamy ułamek zwykły na dziesiętny: $\\frac{2}{5}=0{,}4$.","Mnożymy potęgi o tej samej podstawie — dodajemy wykładniki: $-2{,}4+0{,}4=-2$, więc w nawiasie jest $3^{-2}$.","Potęga potęgi — mnożymy wykładniki: $\\left(3^{-2}\\right)^{\\frac12}=3^{-2\\cdot\\frac12}=3^{-1}=\\frac{1}{3}$.","Odpowiedź: $\\frac{1}{3}$."],"2308-5":["Pomysł: ujemny wykładnik odwraca ułamek; potęga parzysta liczby ujemnej jest dodatnia.","$3^{-1}=\\frac{1}{3}$.","$\\left(-\\frac{1}{9}\\right)^{-2}$: minus w wykładniku odwraca ułamek, $\\left(-9\\right)^{2}=9\\cdot 9=81$ (kwadrat liczby ujemnej jest dodatni).","$\\frac{1}{3}:81\\cdot 81=\\frac{1}{3}\\cdot\\frac{81}{81}=\\frac{81}{243}=\\frac{1}{3}$.","Odpowiedź: $\\frac{1}{3}$."],"2412-2":["Pomysł: wszystko zapisujemy jako potęgi tej samej liczby, potem dodajemy i mnożymy wykładniki.","Zamieniamy na potęgi o podstawie $5$: $\\sqrt[5]{5}=5^{\\frac1{5}}$, $\\frac{1}{5}=5^{-1}$.","W nawiasie dodajemy wykładniki: $\\frac{1}{5}+(-1)=\\frac{1}{5}-\\frac{5}{5}=-\\frac{4}{5}$.","Potęga potęgi — mnożymy wykładniki: $-\\frac{4}{5}\\cdot(-5)=4$, więc wynik to $5^{4}$.","Odpowiedź: $5^{4}$."],"2506-2":["Pomysł: wszystkie liczby zapisujemy jako potęgi tej samej podstawy (np. $8=2^3$, $\\frac1{16}=2^{-4}$). Potem przy mnożeniu dodajemy wykładniki, przy dzieleniu odejmujemy.","Zapisujemy wszystko jako potęgi dwójki: $256=2^{8}$, $\\ 8=2^{3}$.","$8^2=\\left(2^{3}\\right)^2=2^{3\\cdot 2}=2^{6}$.","Pierwiastek trzeciego stopnia dzieli wykładnik przez $3$: $\\sqrt[3]{2^{6}}=2^{6:3}=2^{2}$.","Mnożymy, dodając wykładniki: $2^{8}\\cdot 2^{2}=2^{8+2}=2^{10}$.","Odpowiedź: $2^{10}$."],"2508-2":["Pomysł: wszystkie liczby zapisujemy jako potęgi tej samej podstawy (np. $8=2^3$, $\\frac1{16}=2^{-4}$). Potem przy mnożeniu dodajemy wykładniki, przy dzieleniu odejmujemy.","$25=5^2$, więc $25^{-2}=\\left(5^2\\right)^{-2}=5^{2\\cdot(-2)}=5^{-4}$.","$125=5^3$, więc $125^{-4}=5^{3\\cdot(-4)}=5^{-12}$.","Dzielenie potęg o tej samej podstawie — wykładniki odejmujemy: $5^{-4-(-12)}=5^{-4+12}=5^{8}$.","Odpowiedź: $5^{8}$."],"2603-3":["Pomysł: zamieniamy podstawy na potęgi tej samej liczby, potem dodajemy (mnożenie) i odejmujemy (dzielenie) wykładniki.","$9=3^2$ i $27=3^3$, więc $9^{20}=3^{2\\cdot 20}=3^{40}$ oraz $27^{15}=3^{3\\cdot 15}=3^{45}$.","Licznik: $3^{10}\\cdot 3^{40}=3^{10+40}=3^{50}$.","Dzielimy — odejmujemy wykładniki: $3^{50-45}=3^{5}$.","Odpowiedź: $3^{5}$."],"2605-3":["Pomysł: zamieniamy pierwiastki na potęgi: najpierw wewnętrzny, potem zewnętrzny.","Wewnątrz: $5\\sqrt{5}=5^{1}\\cdot 5^{\\frac12}=5^{1+\\frac12}=5^{\\frac32}$.","Zewnętrzny pierwiastek to potęga $\\frac12$: $\\left(5^{\\frac32}\\right)^{\\frac12}=5^{\\frac32\\cdot\\frac12}=5^{\\frac34}$.","Odpowiedź: $5^{\\frac{3}{4}}$."],"2606-2":["Pomysł: zapisujemy $3^{-2k}$ jako potęgę dziewiątki i odejmujemy wykładniki.","Zamieniamy $3$ na potęgę $9$: $9=3^2$, więc $3^{-20}=\\left(3^2\\right)^{-10}=9^{-10}$.","Dzielimy potęgi o tej samej podstawie — odejmujemy wykładniki: $\\frac{9^{4}}{9^{-10}}=9^{4-(-10)}=9^{4+10}=9^{14}$.","Odpowiedź: $9^{14}$."],"2605-1":["Pomysł: pierwiastki możemy mnożyć „pod jednym dachem”: $\\sqrt a\\cdot\\sqrt b=\\sqrt{ab}$. Potem upraszczamy i dodajemy resztę.","Pierwiastki możemy pomnożyć „pod jednym pierwiastkiem”: $\\sqrt{\\frac{25}{8}}\\cdot\\sqrt{2}=\\sqrt{\\frac{25}{8}\\cdot 2}$.","Mnożymy ułamek przez liczbę (liczba trafia do licznika): $\\frac{25}{8}\\cdot 2=\\frac{25\\cdot 2}{8}=\\frac{50}{8}=\\frac{50:2}{8:2}=\\frac{25}{4}$.","$\\sqrt{\\frac{25}{4}}=\\frac{\\sqrt{25}}{\\sqrt{4}}=\\frac{5}{2}$.","$2^{-1}=\\frac{1}{2}$.","Dodajemy: $\\frac{5}{2}+\\frac{1}{2}=\\frac{5+1}{2}=\\frac{6}{2}=3$.","Odpowiedź: $3$."],"2308-2":["Pomysł: dodawać i odejmować można tylko „takie same” pierwiastki. Dlatego najpierw wyłączamy czynnik przed pierwiastek, tak aby pod pierwiastkami została ta sama liczba.","Rozkładamy liczbę pod pierwiastkiem tak, by wyłączyć kwadrat: $\\sqrt{45}=\\sqrt{9\\cdot 5}=\\sqrt{9}\\cdot\\sqrt{5}=3\\sqrt{5}$.","Tak samo: $\\sqrt{20}=\\sqrt{4\\cdot 5}=2\\sqrt{5}$.","Podstawiamy: $3\\cdot 3\\sqrt{5}-2\\sqrt{5}=9\\sqrt{5}-2\\sqrt{5}$.","To „te same” pierwiastki, więc odejmujemy liczby przed nimi: $(9-2)\\sqrt{5}=7\\sqrt{5}$.","Pierwiastek kwadratowy to potęga $\\frac12$: $7\\sqrt{5}=7\\cdot 5^{\\frac12}$.","Odpowiedź: $7\\cdot 5^{\\frac12}$."],"2406-3":["Pomysł: wzór $(a+b)^2=a^2+2ab+b^2$; liczba przed pierwiastkiem też idzie do kwadratu.","Wzór: $(a+b)^2=a^2+2ab+b^2$, tutaj $a=2\\sqrt{10}$, $b=\\sqrt{2}$.","$a^2=2^2\\cdot(\\sqrt{10})^2=4\\cdot 10=40$; $b^2=2$.","$2ab=2\\cdot 2\\sqrt{10}\\cdot\\sqrt{2}=4\\sqrt{20}=4\\cdot 2\\sqrt{5}=8\\sqrt{5}$.","Razem: $40+2+8\\sqrt{5}=42+8\\sqrt{5}$.","Odpowiedź: $42+8\\sqrt{5}$."],"2505-1":["Pomysł: najpierw upraszczamy większy pierwiastek (wyłączamy kwadrat liczby), potem odejmujemy i podnosimy do kwadratu.","Wyłączamy czynnik spod pierwiastka: $\\sqrt{32}=\\sqrt{16\\cdot 2}=4\\sqrt{2}$.","W nawiasie: $4\\sqrt{2}-\\sqrt{2}=3\\sqrt{2}$.","Do kwadratu: $\\left(3\\sqrt{2}\\right)^2=9\\cdot 2=18$.","Odpowiedź: $18$."],"2508-3":["Pomysł: z liczby pod pierwiastkiem sześciennym wyłączamy sześcian ($8$, $27$, $64$, $125$…), aby pod oboma pierwiastkami została ta sama liczba — wtedy je dodajemy.","Szukamy sześcianu ($8, 27, 64, 125\\ldots$), który dzieli liczbę pod pierwiastkiem: $24=8\\cdot 3$, a $8=2^3$.","$\\sqrt[3]{24}=\\sqrt[3]{8}\\cdot\\sqrt[3]{3}=2\\sqrt[3]{3}$.","Tak samo: $192=64\\cdot 3$, więc $\\sqrt[3]{192}=4\\sqrt[3]{3}$.","Dodajemy liczby przed tym samym pierwiastkiem: $2\\sqrt[3]{3}+4\\sqrt[3]{3}=(2+4)\\sqrt[3]{3}=6\\sqrt[3]{3}$.","Odpowiedź: $6\\sqrt[3]{3}$."],"2603-2":["Pomysł: łączymy w jeden pierwiastek trzeciego stopnia i skracamy ułamek pod nim.","Łączymy w jeden pierwiastek: $\\sqrt[3]{\\frac{50\\cdot(-15)}{2\\cdot 3}}$.","Skracamy: $\\frac{50}{2}=25$ i $\\frac{-15}{3}=-5$, więc pod pierwiastkiem jest $25\\cdot(-5)=-125$.","$\\sqrt[3]{-125}=-5$, bo $(-5)^3=-125$.","Odpowiedź: $\\left(-5\\right)$."],"inf-6":["Pomysł: wyłączamy sześciany spod pierwiastków — w liczniku i mianowniku zostaje ten sam pierwiastek, który się skraca.","Wyłączamy sześciany: $\\sqrt[3]{250}=\\sqrt[3]{125\\cdot 2}=5\\sqrt[3]{2}$ oraz $\\sqrt[3]{54}=\\sqrt[3]{27\\cdot 2}=3\\sqrt[3]{2}$.","Licznik: $5\\sqrt[3]{2}+3\\sqrt[3]{2}=8\\sqrt[3]{2}$; mianownik: $2\\sqrt[3]{2}$.","$\\frac{8\\sqrt[3]{2}}{2\\sqrt[3]{2}}=4$ ($\\sqrt[3]{2}$ się skraca).","Odpowiedź: $4$."],"2606-1":["Pomysł: pierwiastek <b>nieparzystego</b> stopnia z liczby ujemnej istnieje i jest ujemny, np. $\\sqrt[3]{-8}=-2$, bo $(-2)^3=-8$.","Liczymy każdy pierwiastek: $\\sqrt[3]{-64}=-4$ (bo $(-4)^3=-64$), $\\ \\sqrt[3]{27}=3$ (bo $3^3=27$).","$\\sqrt[5]{-32}=-2$, bo $(-2)^5=-32$ — pierwiastek nieparzystego stopnia z liczby ujemnej jest ujemny.","Licznik: $-4+3=-1$.","Ułamek: $\\frac{-1}{-2}$ — minus przez minus daje plus: $\\frac{1}{2}$.","Odpowiedź: $\\frac{1}{2}$."],"2608-1":["Pomysł: pierwiastek <b>nieparzystego</b> stopnia z liczby ujemnej istnieje i jest ujemny, np. $\\sqrt[3]{-8}=-2$, bo $(-2)^3=-8$.","$\\sqrt[3]{-27}=-3$, bo $(-3)\\cdot(-3)\\cdot(-3)=-27$ (trzy minusy dają minus).","$\\sqrt[5]{-1}=-1$, bo $(-1)^5=-1$ (nieparzysta liczba minusów daje minus).","Dodajemy: $-3+(-1)=-3-1=-4$.","Odpowiedź: $\\left(-4\\right)$."],"2305-2":["Pomysł: iloczyn pierwiastków tego samego stopnia to pierwiastek z iloczynu. Mnożymy liczby pod pierwiastkiem, a potem wyciągamy pierwiastek z licznika i mianownika.","Oba pierwiastki są stopnia $3$, więc łączymy je w jeden: $\\sqrt[3]{x}\\cdot\\sqrt[3]{y}=\\sqrt[3]{x\\cdot y}$.","Mnożymy pod pierwiastkiem: $-\\frac{27}{16}\\cdot 2=-\\frac{27}{8}$ (skracamy $2$).","$\\sqrt[3]{-\\frac{27}{8}}=-\\frac{3}{2}$, bo $\\left(-\\frac{3}{2}\\right)^3=-\\frac{27}{8}$ — pierwiastek trzeciego stopnia z liczby ujemnej jest ujemny.","Odpowiedź: $\\left(-\\frac{3}{2}\\right)$."],"2306-2":["Pomysł: każdy pierwiastek zamieniamy na potęgę: $\\sqrt[n]{x}=x^{\\frac1n}$. Przy mnożeniu potęg o tej samej podstawie wykładniki się dodaje.","Zamieniamy każdy pierwiastek na potęgę: $\\sqrt[n]{x}=x^{\\frac1n}$, więc $\\sqrt{x}\\cdot \\sqrt[3]{x}\\cdot \\sqrt[6]{x}=x^{\\frac1{2}}\\cdot x^{\\frac1{3}}\\cdot x^{\\frac1{6}}$.","Przy mnożeniu potęg o tej samej podstawie dodajemy wykładniki. Sprowadzamy ułamki do wspólnego mianownika: $\\frac{1}{2}+\\frac{1}{3}+\\frac{1}{6}=\\frac{3}{6}+\\frac{2}{6}+\\frac{1}{6}=\\frac{3+2+1}{6}=\\frac{6}{6}=1$.","Wynik: $x^{1}$.","Odpowiedź: $x$."],"2505-2":["Pomysł: w liczniku wyłączamy przed nawias najmniejszą potęgę — wtedy da się ją skrócić z mianownikiem.","Każdy składnik licznika zawiera $5^{12}$: $5^{13}=5^{12}\\cdot 5$, $\\ 5^{14}=5^{12}\\cdot 5^2$.","Wyłączamy $5^{12}$ przed nawias: $5^{12}+5^{13}+5^{14}=5^{12}\\cdot(1+5+5^2)$.","Skracamy z mianownikiem $5^{12}$ — zostaje nawias: $1+5+5^2$.","$1+5+25=31$.","Odpowiedź: $31$."],"2412-5":["Pomysł: z wzoru na procent składany wyznaczamy $(1+\\frac{p}{100})^2$ i pierwiastkujemy.","Wzór na procent składany: $60\\,000\\cdot\\left(1+\\frac{p}{100}\\right)^2=67\\,925{,}76$.","Dzielimy przez $60\\,000$: $\\left(1+\\frac{p}{100}\\right)^2=1{,}132096$.","Pierwiastkujemy: $1+\\frac{p}{100}=\\sqrt{1{,}132096}=1{,}064$, więc $\\frac{p}{100}=0{,}064$ i $p=6{,}4$.","Odpowiedź: $6{,}4\\%$."],"2406-4":["Pomysł: każdy okres oszczędzania mnoży kwotę przez ten sam czynnik $1+\\frac{p}{100}$, więc po $n$ okresach mnożymy przez ten czynnik $n$ razy, czyli podnosimy do potęgi $n$.","Odsetki $6\\%$ to $\\frac{6}{100}$ kwoty. Kwota z odsetkami: $K+\\frac{6}{100}K=K\\cdot\\left(1+\\frac{6}{100}\\right)=K\\cdot 1{,}06$.","Po 1. roku: $K_0\\cdot 1{,}06$; po 2. roku: $K_0\\cdot 1{,}06\\cdot 1{,}06=K_0\\cdot(1{,}06)^2$; po 3. roku: $K_0\\cdot(1{,}06)^3$.","Po $3$ latach mnożymy przez $1{,}06$ dokładnie $3$ razy: $K_0\\cdot(1{,}06)^{3}$.","Odpowiedź: $K_0\\cdot(1{,}06)^{3}$."],"inf-9":["Pomysł: po $n$ latach kwota mnoży się przez $(1+\\frac{p}{100})^n$ — liczymy to kalkulatorem.","Po każdym roku kwota mnoży się przez $1+\\frac{3}{100}=1{,}03$. Po $10$ latach: $K\\cdot 1{,}03^{10}$.","$1{,}03^{10}\\approx 1{,}3439$ (kalkulator), czyli kwota to około $134{,}39\\%$ wpłaty.","Wzrost: $134{,}39\\%-100\\%\\approx 34\\%$.","Odpowiedź: $34\\%$."],"2505-4":["Pomysł: rozwijamy oba kwadraty ze wzoru $(a\\pm b)^2=a^2\\pm2ab+b^2$, a potem odejmujemy — minus przed drugim nawiasem zmienia znak <b>każdego</b> jego wyrazu.","Wzór: $(A\\pm B)^2=A^2\\pm2AB+B^2$.","$(3x+2)^2=(3x)^2+2\\cdot 3x\\cdot 2+2^2=9x^{2}+12x+4$.","$(2x-3)^2=(2x)^2-2\\cdot 2x\\cdot 3+3^2=4x^{2}-12x+9$.","Odejmujemy — minus zmienia znak każdego wyrazu drugiego nawiasu: $9x^{2}+12x+4-4x^{2}+12x-9$.","Łączymy wyrazy podobne ($x^2$ z $x^2$, $x$ z $x$, liczby z liczbami): $5x^{2}+24x-5$.","Odpowiedź: $5x^{2}+24x-5$."],"2508-6":["Pomysł: rozwijamy oba kwadraty ze wzoru $(a\\pm b)^2=a^2\\pm2ab+b^2$, a potem odejmujemy — minus przed drugim nawiasem zmienia znak <b>każdego</b> jego wyrazu.","Wzory: $(A+B)^2=A^2+2AB+B^2$, $(A-B)^2=A^2-2AB+B^2$, gdzie $A=3x$, $B=y$.","$A^2=(3x)^2=9x^2$, $\\ B^2=(y)^2=y^2$, $\\ 2AB=2\\cdot 3x\\cdot y=6xy$.","$(3x+y)^2=9x^2+6xy+y^2$ oraz $(3x-y)^2=9x^2-6xy+y^2$.","Odejmujemy — minus przed nawiasem zmienia znak każdego wyrazu: $9x^2+6xy+y^2-9x^2+6xy-y^2$.","Wyrazy z $x^2$ i $y^2$ się znoszą, zostaje $+6xy+6xy=12xy$.","Odpowiedź: $12xy$."],"2209-5":["Pomysł: zwijamy nawias do kwadratu, a potem stosujemy wzór na różnicę kwadratów.","W nawiasie jest kwadrat różnicy: $x^2-2xy+y^2=(x-y)^2$, a $9=3^2$.","Różnica kwadratów: $3^2-(x-y)^2=[3-(x-y)]\\cdot[3+(x-y)]$.","To samo z minusem przed: $[3-(x-y)]=-[(x-y)-3]$, więc też $-[(x-y)-3]\\cdot[(x-y)+3]$."],"2306-6":["Pomysł: rozwijamy oba kwadraty ze wzoru skróconego mnożenia i odejmujemy. Warto zauważyć, że $(a-b)^2=(b-a)^2$ — te same liczby w odwrotnej kolejności dają ten sam kwadrat.","Rozwijamy oba kwadraty ze wzorów skróconego mnożenia, gdzie $a=1$, $b=\\sqrt{5}$: $(a+b)^2=a^2+2ab+b^2$ oraz $(a-b)^2=a^2-2ab+b^2$.","Odejmujemy: $a^2$ i $b^2$ się redukują, a $2ab-(-2ab)=4ab$.","$4ab=4\\cdot 1\\cdot \\sqrt{5}=4\\sqrt{5}$.","Odpowiedź: $4\\sqrt{5}$."],"2308-6":["Pomysł: rozwijamy oba kwadraty ze wzoru skróconego mnożenia i odejmujemy. Warto zauważyć, że $(a-b)^2=(b-a)^2$ — te same liczby w odwrotnej kolejności dają ten sam kwadrat.","Rozwijamy pierwszy kwadrat: $(2-\\sqrt{3})^2=4-4\\sqrt{3}+3$.","Rozwijamy drugi: $(\\sqrt{3}-2)^2=3-4\\sqrt{3}+4$ — to te same składniki, tylko w innej kolejności.","Kwadraty są równe, więc ich różnica to $0$. (Ogólnie: $(a-b)^2=(b-a)^2$.)","Odpowiedź: $0$."],"2608-4":["Pomysł: rozwijamy oba kwadraty ze wzoru skróconego mnożenia i odejmujemy. Warto zauważyć, że $(a-b)^2=(b-a)^2$ — te same liczby w odwrotnej kolejności dają ten sam kwadrat.","Rozwijamy oba kwadraty ze wzorów skróconego mnożenia, gdzie $a=\\pi$, $b=1$: $(a+b)^2=a^2+2ab+b^2$ oraz $(a-b)^2=a^2-2ab+b^2$.","Odejmujemy: $a^2$ i $b^2$ się redukują, a $2ab-(-2ab)=4ab$.","$4ab=4\\cdot \\pi\\cdot 1=4\\pi$.","Odpowiedź: $4\\pi$."],"2506-4":["Pomysł: kwadrat sumy rozwijamy ze wzoru $(a+b)^2=a^2+2ab+b^2$, a pierwiastek upraszczamy, wyłączając czynnik przed pierwiastek — wtedy wyrazy z pierwiastkiem się zredukują.","Wzór: $(a+b)^2=a^2+2ab+b^2$, gdzie $a=\\sqrt{3}$, $b=1$.","$a^2=(\\sqrt{3})^2=3$, $\\ 2ab=2\\cdot\\sqrt{3}\\cdot 1=2\\sqrt{3}$, $\\ b^2=1^2=1$. Razem: $3+2\\sqrt{3}+1$.","Upraszczamy pierwiastek: $\\sqrt{12}=\\sqrt{4\\cdot 3}=2\\sqrt{3}$.","Odejmujemy: $3+2\\sqrt{3}+1-2\\sqrt{3}$ — wyrazy z pierwiastkiem się znoszą: $3+1=4$.","Odpowiedź: $4$."],"2605-6":["Pomysł: zamiast podstawiać od razu, zauważamy wzór skróconego mnożenia: wyrażenie jest kwadratem sumy. Po podstawieniu w nawiasie zostanie prosta liczba.","Rozpoznajemy wzór $(x+a)^2=x^2+2ax+a^2$: tu $2a=10$, więc $a=5$, i rzeczywiście $a^2=25$. Zatem $x^2+10x+25=(x+5)^2$.","Podstawiamy $x=\\sqrt{2}-5$ do nawiasu: $x+5=\\sqrt{2}-5+5=\\sqrt{2}$.","$(\\sqrt{2})^2=2$.","Odpowiedź: $2$."],"inf-25":["Pomysł: podstawiamy miejsce zerowe do wzoru i przyrównujemy do zera.","Miejsce zerowe: $f(\\sqrt{2}+1)=0$, czyli $(\\sqrt{2}+1)^2-b-2\\sqrt{2}=0$.","$(\\sqrt{2}+1)^2=2+2\\cdot 1\\sqrt{2}+1=3+2\\sqrt{2}$.","$3+2\\sqrt{2}-b-2\\sqrt{2}=0$ — pierwiastki się redukują: $3-b=0$, więc $b=3$.","Odpowiedź: $3$."],"2405-8":["Pomysł: każde stwierdzenie sprawdzamy osobno — wymnażamy albo wyłączamy wspólny czynnik, a „rozwiązanie równania” sprawdzamy, podstawiając liczbę.","$3x(x^{2}+2x+3)=3x^{3}+6x^{2}+9x$.","Sprawdzamy, czy $1$ jest rozwiązaniem: podstawiamy $x=1$: $W(1)=3\\cdot 1^3+6\\cdot 1^2+9\\cdot 1=3+6+9=18$ — to nie zero, więc $1$ nie jest rozwiązaniem."],"2606-6":["Pomysł: najpierw wymnażamy $V(x)\\cdot H(x)$ (każdy wyraz przez każdy), potem odejmujemy wynik od $W(x)$, pamiętając o zmianie znaków.","Mnożymy każdy wyraz pierwszego nawiasu przez każdy wyraz drugiego: $(x^{3}+1)(x-2)=x^3\\cdot x+x^3\\cdot (-2)+1\\cdot x+1\\cdot (-2)=x^4-2x^3+x-2$.","Odejmujemy od $x^4$ — minus zmienia znak każdego wyrazu, a $x^4$ się znosi: $x^4-x^4+2x^3-x+2=2x^{3}-x+2$.","Odpowiedź: $2x^{3}-x+2$."],"2606-4":["Pomysł: najpierw wyłączamy wspólny czynnik przed nawias, a w nawiasie szukamy wzoru skróconego mnożenia.","$x^{3}-2x^{2}+x=x(x^{2}-2x+1)$.","$x^{2}-2x+1=(x-1)^2$ — wzór na kwadrat różnicy.","Odpowiedź: $x(x-1)^2$."],"2312-7":["Pomysł: rozkładamy liczniki i mianowniki na czynniki, potem skracamy.","Rozkładamy na czynniki: $x^2+4x+4=(x+2)^2$, $x^2+2x=x(x+2)$, $2x+6=2(x+3)$.","$\\frac{x+3}{(x+2)^2}\\cdot\\frac{x(x+2)}{2(x+3)}$ — skracamy $x+3$ i jedno $x+2$.","Zostaje $\\frac{x}{2(x+2)}=\\frac{x}{2x+4}$.","Odpowiedź: $\\frac{x}{2x+4}$."],"2406-8":["Pomysł: rozkładamy mianownik ze wzoru na różnicę kwadratów i skracamy.","Różnica kwadratów: $x^2-1=(x-1)(x+1)$.","$\\frac{2x^2}{(x-1)(x+1)}\\cdot\\frac{x+1}{x}$ — skracamy $x+1$ oraz jedno $x$.","Zostaje $\\frac{2x}{x-1}$.","Odpowiedź: $\\frac{2x}{x-1}$."],"inf-16":["Pomysł: dziedzina — mianowniki różne od zera; potem rozkład i skracanie.","Dziedzina: $x^2-4\\neq 0$ i $x\\neq 0$, czyli $x\\notin\\{-2, 0, 2\\}$.","Rozkładamy: $x^2-4=(x-2)(x+2)$; skracamy $x-2$ i jedno $x$: $W(x)=\\frac{2x}{x+2}$.","Mianowniki nie mogą być zerem: $x\\neq 0$, $x\\neq 2$, $x\\neq -2$.","$\\frac{2x^2}{(x-2)(x+2)}\\cdot\\frac{x-2}{x}=\\frac{2x}{x+2}$ (skraca się $x-2$ i jedno $x$)."],"2209-4":["Pomysł: liczbę zapisujemy jako ułamek o tym samym mianowniku i odejmujemy liczniki.","Sprowadzamy do wspólnego mianownika: $5=\\frac{5(x-1)}{x-1}$.","$\\frac{2}{x-1}-\\frac{5(x-1)}{x-1}=\\frac{2-5(x-1)}{x-1}$.","Opuszczamy nawias (minus zmienia znaki): $2-5x+5=-5x+7$, więc wynik $\\frac{-5x+7}{x-1}$.","Odpowiedź: $\\frac{-5x+7}{x-1}$."],"2412-6":["Pomysł: dzielenie przez ułamek zamieniamy na mnożenie przez odwrotność, potem rozkład i skracanie.","Dzielenie przez ułamek = mnożenie przez odwrotność: $\\frac{x}{x^2-1}\\cdot\\frac{x+1}{3x^2}$.","$x^2-1=(x-1)(x+1)$; skracamy $x+1$ oraz $x$: $\\frac{1}{(x-1)\\cdot 3x}$.","Wymnażamy mianownik: $3x(x-1)=3x^2-3x$, więc $\\frac{1}{3x^2-3x}$.","Odpowiedź: $\\frac{1}{3x^2-3x}$."],"2603-6":["Pomysł: licznik zwijamy do kwadratu sumy i skracamy.","Licznik to kwadrat sumy: $x^2+20x+100=(x+10)^2$.","$\\frac{(x+10)^2}{x^3}\\cdot\\frac{x^2}{x+10}$ — skracamy jedno $x+10$ oraz $x^2$ z $x^3$.","Zostaje $\\frac{x+10}{x}$.","Odpowiedź: $\\frac{x+10}{x}$."],"2608-8":["Pomysł: najpierw rozkładamy liczniki i mianowniki na czynniki (wyłączanie przed nawias, wzory skróconego mnożenia), a dopiero potem skracamy — skracać wolno tylko czynniki, nigdy składniki sumy.","Rozkładamy mianowniki na czynniki: $x^2+2x=x(x+2)$ (wyłączamy $x$) oraz $4-x^2=(2-x)(2+x)$ (wzór $A^2-B^2=(A-B)(A+B)$).","Dzielenie przez ułamek to mnożenie przez jego odwrotność: $\\frac{4}{x(x+2)}:\\frac{5x}{(2-x)(2+x)}=\\frac{4}{x(x+2)}\\cdot\\frac{(2-x)(2+x)}{5x}$.","Mnożymy: $\\frac{4\\cdot(2-x)(2+x)}{x(x+2)\\cdot 5x}$. Skracamy wspólny czynnik $(x+2)=(2+x)$.","Zostaje $\\frac{4(2-x)}{5x\\cdot x}=\\frac{4(2-x)}{5x^2}=\\frac{8-4x}{5x^2}$.","Odpowiedź: $\\frac{8-4x}{5x^2}$."],"inf-17":["Pomysł: mnożymy przez wspólny mianownik $6$, rozwiązujemy i zaznaczamy na osi.","Mnożymy obie strony przez $6$ (wspólny mianownik): $3(2x-1)-2(x+2)\\geq 1$.","Opuszczamy nawiasy: $6x-3-2x-4\\geq 1$, czyli $4x-7\\geq 1$.","$4x\\geq 1+7=8$, więc $x\\geq 8:4=2$. Na osi: od $2$ w prawo, kółko zamalowane."],"2405-6":["Pomysł: zbieramy $x$ po jednej stronie; dzieląc przez liczbę ujemną, zmieniamy zwrot.","Wyrazy z $x$ na lewo, liczby na prawo: $-\\frac{3}{2}x+x<\\frac{2}{3}-1$.","$-\\frac{3}{2}x+\\frac{2}{2}x=-\\frac{1}{2}x$, a $\\frac{2}{3}-1=\\frac{2}{3}-\\frac{3}{3}=-\\frac{1}{3}$. Więc $-\\frac{1}{2}x<-\\frac{1}{3}$.","Dzielimy przez $-\\frac{1}{2}$ (liczba ujemna — zmieniamy zwrot): $x>-\\frac{1}{3}:\\left(-\\frac{1}{2}\\right)=\\frac{2}{3}$.","Odpowiedź: $\\left(\\frac{2}{3}, +\\infty\\right)$."],"2408-5":["Pomysł: pozbywamy się ułamka i liczby przed nawiasem, a na końcu mnożymy przez $-1$ ze zmianą zwrotu.","Mnożymy obie strony przez $17$: $3(6-x)\\le 51$.","Dzielimy przez $3$: $6-x\\le 17$.","$-x\\le 17-6=11$; mnożymy przez $-1$ (zmiana zwrotu): $x\\ge -11$, czyli $[-11, +\\infty)$.","Odpowiedź: $[-11, +\\infty)$."],"2508-7":["Pomysł: mnożymy obie strony przez $2$ i zbieramy $x$ po jednej stronie.","Mnożymy obie strony przez $2$: $6-2x\\ge 5x-1$.","Wyrazy z $x$ na prawo, liczby na lewo: $6+1\\ge 5x+2x$, czyli $7\\ge 7x$.","Dzielimy przez $7$: $x\\le 7:7=1$, czyli $(-\\infty, 1]$.","Odpowiedź: $(-\\infty, 1]$."],"2506-6":["Pomysł: rozwiązujemy nierówność, a potem wybieramy największą liczbę całkowitą z przedziału.","Mnożymy przez $2$: $16-(1-2x)\\ge 6x$, czyli $16-1+2x\\ge 6x$.","$15\\ge 6x-2x=4x$, więc $x\\le\\frac{15}{4}=3{,}75$.","Największa liczba całkowita nie większa od $3{,}75$ to $3$.","Odpowiedź: $3$."],"2305-7":["Pomysł: iloczyn jest równy zero wtedy i tylko wtedy, gdy któryś z czynników jest równy zero. Każdy czynnik rozwiązujemy osobno.","Iloczyn jest zerem, gdy któryś czynnik jest zerem. Liczba przed nawiasami nie jest zerem.","$x^2-2=0$ oznacza $x^2=2$, czyli $x=\\sqrt{2}$ lub $x=-\\sqrt{2}$.","$x+3=0$ oznacza $x=-3$.","Wśród odpowiedzi jest $\\sqrt{2}$.","Odpowiedź: $\\sqrt{2}$."],"2605-8":["Pomysł: iloczyn jest równy zero wtedy i tylko wtedy, gdy któryś z czynników jest równy zero. Każdy czynnik rozwiązujemy osobno.","Iloczyn jest równy zero, gdy któryś czynnik jest zerem. Liczba $3$ nigdy nie jest zerem.","$x+3=0\\Rightarrow x=-3$; $\\ x-m=0\\Rightarrow x=m$; $\\ 2x+4=0\\Rightarrow x=-2$.","Suma rozwiązań: $-3+m+(-2)=0$, więc $m=5$.","Odpowiedź: $5$."],"2608-7":["Pomysł: $x^2=c$ daje rozwiązania $\\pm\\sqrt c$ — w sumie się znoszą.","$x^2-4=0\\Rightarrow x=2$ lub $x=-2$; $x^2-9=0\\Rightarrow x=3$ lub $x=-3$.","Suma: $2+(-2)+3+(-3)=0$.","Odpowiedź: $0$."],"2306-1":["Pomysł: nierówność z wartością bezwzględną zamieniamy na podwójną nierówność, a potem wypisujemy (albo liczymy) liczby całkowite z otrzymanego przedziału.","$|A|<15$ oznacza $-15<A<15$: $-15<x+5<15$.","Odejmujemy $5$ od każdej strony: $-15-5<x<15-5$, czyli $-20<x<10$.","Liczby całkowite dodatnie z tego przedziału (końce nie należą): $1, 2, \\ldots, 9$ — jest ich $9$.","Odpowiedź: $9$."],"2408-1":["Pomysł: nierówność z wartością bezwzględną zamieniamy na podwójną nierówność, a potem wypisujemy (albo liczymy) liczby całkowite z otrzymanego przedziału.","$|A|<3$ oznacza $-3<A<3$: $-3<x+1<3$.","Odejmujemy $1$ od każdej strony: $-3-1<x<3-1$, czyli $-4<x<2$.","Liczby całkowite z tego przedziału (końce nie należą): od $-3$ do $1$. Ile ich jest: $1-(-3)+1=5$.","Odpowiedź: $5$."],"2308-1":["Pomysł: $|x-a|\\le r$ oznacza punkty odległe od $a$ o co najwyżej $r$ — to przedział od $a-r$ do $a+r$ (przy „<” bez końców).","$|x-5|$ to odległość liczby $x$ od $5$ na osi.","Od $5$ odmierzamy $2$ w lewo i w prawo: $5-2=3$ oraz $5+2=7$.","Odległość mniejsza $2$ — to punkty między tymi liczbami: $3< x< 7$. Kółka puste (końce nie należą)."],"2405-1":["Pomysł: $|x-a|\\le r$ oznacza punkty odległe od $a$ o co najwyżej $r$ — to przedział od $a-r$ do $a+r$ (przy „<” bez końców).","$|x-1|$ to odległość liczby $x$ od $1$ na osi.","Od $1$ odmierzamy $3$ w lewo i w prawo: $1-3=-2$ oraz $1+3=4$.","Odległość większa lub równa $3$ — to punkty na zewnątrz tymi liczbami: $x\\leq -2$ lub $x\\geq 4$. Kółka zamalowane (końce należą)."],"2412-1":["Pomysł: $|x+a|=b$ oznacza $x+a=b$ lub $x+a=-b$.","$|x+4|=7$ oznacza $x+4=7$ lub $x+4=-7$.","$x_1=7-4=3$, $x_2=-7-4=-11$.","Suma: $3+(-11)=-8$.","Odpowiedź: $\\left(-8\\right)$."],"2506-1":["Pomysł: $|x-a|=r$ oznacza, że $x$ leży w odległości $r$ od $a$ — czyli $x=a-r$ albo $x=a+r$.","$|x-6|$ to odległość $x$ od liczby $6$. Ma być równa $4$.","Są dwie takie liczby: $6-4=2$ (w lewo) oraz $6+4=10$ (w prawo).","Iloczyn: $2\\cdot 10=20$.","Odpowiedź: $20$."],"2508-1":["Pomysł: o znaku wyrażenia pod wartością bezwzględną decyduje przybliżenie pierwiastka. Wyrażenie dodatnie zostaje bez zmian, ujemne zmienia znak.","$\\sqrt{5}\\approx 2{,}24$ (bo $2^2=4$ i $3^2=9$).","$\\sqrt{5}-3<0$ — wartość bezwzględna zmienia znak: $|\\sqrt{5}-3|=3-\\sqrt{5}$.","$\\sqrt{5}-1>0$ — zostaje bez zmian: $|\\sqrt{5}-1|=\\sqrt{5}-1$.","Dodajemy: $3-\\sqrt{5}+\\sqrt{5}-1$ — pierwiastki się znoszą, zostaje $3-1=2$.","Odpowiedź: $2$."],"2603-9":["Pomysł: wyłączamy wspólny czynnik — dostajemy od razu $x+y$ oraz $x-y$.","Wyłączamy wspólny czynnik: $20(x+y)=1$ i $26(x-y)=1$, więc $x+y=\\frac{1}{20}$, $x-y=\\frac{1}{26}$.","Dodajemy równania: $2x=\\frac{23}{260}$, $x=\\frac{23}{520}$; odejmujemy: $2y=\\frac{3}{260}$, $y=\\frac{3}{520}$.","Z pierwszego równania: $20(x_0+y_0)=1$, więc $x_0+y_0=\\frac{1}{20}$.","$x_0=\\frac{23}{520}$, $y_0=\\frac{3}{520}$ — iloczyn dodatni."],"2209-9":["Pomysł: wartość = liczba banknotów · nominał; drugie równanie z zależności „o ... mniej”.","Banknotów $100$-zł jest $2x$, więc są warte $100\\cdot 2x$ zł; $50$-zł: $50x$ zł; $20$-zł: $20y$ zł. Razem: $20y+50x+100\\cdot 2x=1040$.","„$20$-złotowych o $2$ mniej niż $50$-złotowych”: $y=x-2$.","Odpowiedź: $\\begin{cases}20y+50x+100\\cdot 2x=1040\\\\y=x-2\\end{cases}$."],"2305-11":["Pomysł: obwód to $2a+2b$, a „o $d$ krótszy” to $a-b=d$.","Obwód: $2a+2b=30$ (to samo co $2(a+b)=30$).","Krótszy bok $b$ jest o $5$ mniejszy: $b=a-5$, czyli $a-b=5$."],"2508-12.1":["Pomysł: wszystko odczytujemy z rysunku. Dziedzina to „cień” wykresu na osi $Ox$, zbiór wartości — na osi $Oy$. Zamalowane kółko oznacza, że punkt należy do wykresu, puste — że nie należy.","Miejsce zerowe to argument, dla którego $f(x)=0$ — na rysunku: punkt wspólny wykresu z osią $Ox$.","Odczytujemy pierwsze współrzędne tych punktów: $2$. (Uwaga: punkt przecięcia z osią $Oy$ to co innego — to $f(0)$.)","Odpowiedź: $2$."],"2603-11.2":["Pomysł: wszystko odczytujemy z rysunku. Dziedzina to „cień” wykresu na osi $Ox$, zbiór wartości — na osi $Oy$. Zamalowane kółko oznacza, że punkt należy do wykresu, puste — że nie należy.","Funkcja jest malejąca tam, gdzie wykres (czytany od lewej do prawej) opada.","Na rysunku wykres opada dla $x\\in[-4, -2]$ — w innych proponowanych przedziałach są fragmenty, gdzie rośnie lub jest stały.","Odpowiedź: $[-4, -2]$."],"2605-12.1":["Pomysł: wszystko odczytujemy z rysunku. Dziedzina to „cień” wykresu na osi $Ox$, zbiór wartości — na osi $Oy$. Zamalowane kółko oznacza, że punkt należy do wykresu, puste — że nie należy.","Miejsce zerowe to argument, dla którego $f(x)=0$ — na rysunku: punkt wspólny wykresu z osią $Ox$.","Odczytujemy pierwsze współrzędne tych punktów: $1$. (Uwaga: punkt przecięcia z osią $Oy$ to co innego — to $f(0)$.)","Odpowiedź: $1$."],"2606-12.2":["Pomysł: wszystko odczytujemy z rysunku. Dziedzina to „cień” wykresu na osi $Ox$, zbiór wartości — na osi $Oy$. Zamalowane kółko oznacza, że punkt należy do wykresu, puste — że nie należy.","Dziedzina to wszystkie argumenty $x$, dla których narysowano wykres — patrzymy na oś $Ox$ („cień” wykresu).","Wykres zaczyna się nad $x=-4$ i kończy nad $x=3$.","Na lewym końcu kółko jest puste — liczba nie należy (nawias okrągły), na prawym puste (nawias okrągły).","Odpowiedź: $(-4, 3)$."],"2305-12.1":["Pomysł: wszystko odczytujemy z rysunku. Dziedzina to „cień” wykresu na osi $Ox$, zbiór wartości — na osi $Oy$. Zamalowane kółko oznacza, że punkt należy do wykresu, puste — że nie należy.","Dziedzina to wszystkie argumenty $x$, dla których narysowano wykres — patrzymy na oś $Ox$ („cień” wykresu).","Wykres zaczyna się nad $x=-6$ i kończy nad $x=5$.","Na lewym końcu kółko jest puste — liczba nie należy (nawias okrągły), na prawym puste (nawias okrągły).","Odpowiedź: $(-6, 5)$."],"2305-12.3":["Pomysł: wszystko odczytujemy z rysunku. Dziedzina to „cień” wykresu na osi $Ox$, zbiór wartości — na osi $Oy$. Zamalowane kółko oznacza, że punkt należy do wykresu, puste — że nie należy.","Funkcja jest malejąca tam, gdzie wykres (czytany od lewej do prawej) opada.","Na rysunku wykres opada dla $x\\in[2, 5]$ — w innych proponowanych przedziałach są fragmenty, gdzie rośnie lub jest stały.","Odpowiedź: $[2, 5]$."],"2306-13.2":["Pomysł: wszystko odczytujemy z rysunku. Dziedzina to „cień” wykresu na osi $Ox$, zbiór wartości — na osi $Oy$. Zamalowane kółko oznacza, że punkt należy do wykresu, puste — że nie należy.","Rysujemy w myślach poziomą prostą $y=-1$.","Szukamy argumentów $x$, dla których wykres leży <b>poniżej</b> tej prostej (bez punktów na niej — nierówność jest ostra).","Odczytujemy z osi $Ox$: $(-4, 0)$.","Odpowiedź: $(-4, 0)$."],"2603-11.1":["Pomysł: wszystko odczytujemy z rysunku. Dziedzina to „cień” wykresu na osi $Ox$, zbiór wartości — na osi $Oy$. Zamalowane kółko oznacza, że punkt należy do wykresu, puste — że nie należy.","Funkcja jest rosnąca tam, gdzie wykres (czytany od lewej do prawej) wznosi się.","Na rysunku wykres wznosi się dla $x\\in[-4, -1]$ — w innych proponowanych przedziałach są fragmenty, gdzie maleje lub jest stały.","Odpowiedź: $[-4, -1]$."],"inf-27.2":["Pomysł: wszystko odczytujemy z rysunku. Dziedzina to „cień” wykresu na osi $Ox$, zbiór wartości — na osi $Oy$. Zamalowane kółko oznacza, że punkt należy do wykresu, puste — że nie należy.","Najniższy punkt wykresu: $y=-3$, najwyższy: $y=3$.","Zbiór wartości: $(-3, 3]$.","Odpowiedź: $(-3, 3]$."],"2306-13.1":["Pomysł: wszystko odczytujemy z rysunku. Dziedzina to „cień” wykresu na osi $Ox$, zbiór wartości — na osi $Oy$. Zamalowane kółko oznacza, że punkt należy do wykresu, puste — że nie należy.","Najniższy punkt wykresu: $y=-4$, najwyższy: $y=2$.","Zbiór wartości: $[-4, 2)$.","Odpowiedź: $[-4, 2)$."],"2508-12.2":["Pomysł: wszystko odczytujemy z rysunku. Dziedzina to „cień” wykresu na osi $Ox$, zbiór wartości — na osi $Oy$. Zamalowane kółko oznacza, że punkt należy do wykresu, puste — że nie należy.","Najniższy punkt wykresu: $y=-4$, najwyższy: $y=2$.","Zbiór wartości: $[-4, 2]$.","Odpowiedź: $[-4, 2]$."],"2603-11.3":["Pomysł: wszystko odczytujemy z rysunku. Dziedzina to „cień” wykresu na osi $Ox$, zbiór wartości — na osi $Oy$. Zamalowane kółko oznacza, że punkt należy do wykresu, puste — że nie należy.","Funkcja jest malejąca tam, gdzie wykres (czytany od lewej do prawej) opada.","Na rysunku wykres opada dla $x\\in[-3, -2]$ — w innych proponowanych przedziałach są fragmenty, gdzie rośnie lub jest stały.","Odpowiedź: $[-3, -2]$."],"2608-11":["Pomysł: wszystko odczytujemy z rysunku. Dziedzina to „cień” wykresu na osi $Ox$, zbiór wartości — na osi $Oy$. Zamalowane kółko oznacza, że punkt należy do wykresu, puste — że nie należy.","Najniższy punkt wykresu: $y=1$, najwyższy: $y=4$.","Zbiór wartości: $[1, 4]$.","Odpowiedź: $[1, 4]$."],"2412-10":["Pomysł: wszystko odczytujemy z rysunku. Dziedzina to „cień” wykresu na osi $Ox$, zbiór wartości — na osi $Oy$. Zamalowane kółko oznacza, że punkt należy do wykresu, puste — że nie należy.","Funkcja jest rosnąca tam, gdzie wykres (czytany od lewej do prawej) wznosi się.","Na rysunku wykres wznosi się dla $x\\in[0, 3]$ — w innych proponowanych przedziałach są fragmenty, gdzie maleje lub jest stały.","Odpowiedź: $[0, 3]$."],"2505-11":["Pomysł: wszystko odczytujemy z rysunku. Dziedzina to „cień” wykresu na osi $Ox$, zbiór wartości — na osi $Oy$. Zamalowane kółko oznacza, że punkt należy do wykresu, puste — że nie należy.","Najniższy punkt wykresu: $y=-4$, najwyższy: $y=3$.","Zbiór wartości: $[-4, 3]$.","Odpowiedź: $[-4, 3]$."],"2506-10":["Pomysł: wszystko odczytujemy z rysunku. Dziedzina to „cień” wykresu na osi $Ox$, zbiór wartości — na osi $Oy$. Zamalowane kółko oznacza, że punkt należy do wykresu, puste — że nie należy.","Najniższy punkt wykresu: $y=-4$, najwyższy: $y=4$.","Zbiór wartości: $[-4, 4]$.","Odpowiedź: $[-4, 4]$."],"2308-12":["Pomysł: warunek $f(x_0)=y_0$ oznacza: podstaw $x_0$ do wzoru i przyrównaj do $y_0$ — powstaje równanie z jedną niewiadomą.","Podstawiamy argument do wzoru i przyrównujemy do podanej wartości: $\\frac{1-k}{2}=2$.","Mnożymy obie strony przez $2$: $1-k=4$.","Przenosimy: $k=1-4=-3$.","Odpowiedź: $\\left(-3\\right)$."],"2406-12":["Pomysł: w tabeli górny wiersz to argumenty $x$, dolny — wartości $f(x)$. Miejsce zerowe to argument, dla którego wartość jest równa $0$.","Miejsca zerowe (gdzie $y=0$): $-1,\\ 0$.","Dla $x$ i $-x$ wartości nie zawsze są równe."],"2408-9":["Pomysł: w tabeli górny wiersz to argumenty $x$, dolny — wartości $f(x)$. Miejsce zerowe to argument, dla którego wartość jest równa $0$.","Wartości funkcji to liczby w dolnym wierszu tabeli.","Największa z nich to $3$ (dla argumentu $x=2$).","Odpowiedź: $3$."],"inf-22":["Pomysł: w tabeli górny wiersz to argumenty $x$, dolny — wartości $f(x)$. Miejsce zerowe to argument, dla którego wartość jest równa $0$.","Wartości funkcji to liczby w dolnym wierszu tabeli.","Największa z nich to $5$ (dla argumentu $x=-2$).","Odpowiedź: $5$."],"2308-14.3":["Pomysł: $f(x+a)$ przesuwa wykres poziomo (w lewo, gdy $a>0$), $f(x)+b$ — pionowo, $f(-x)$ odbija względem osi $Oy$, a $-f(x)$ względem osi $Ox$.","Zamiana $x$ na $-x$ odbija wykres względem osi $Oy$ (lewa strona zamienia się z prawą).","Każdy punkt $(x, y)$ przechodzi w $(-x, y)$.","Wybieramy rysunek, na którym cały wykres został przekształcony właśnie w ten sposób."],"2408-11.1":["Pomysł: masa całkowita = masa stała (pusty pojemnik) + masa zależna od ilości cieczy. Stała część to wyraz wolny, a masa jednego litra — współczynnik przy $x$.","Masa całkowita to masa pustego pojemnika plus masa cieczy: $f(x)=6+1{,}03x$.","$f(0)=6$ — to masa pustego pojemnika.","Najmniejsza wartość to $f(0)=6>0$ — masa nigdy nie jest zerem."],"2408-11.2":["Pomysł: masa całkowita = masa stała (pusty pojemnik) + masa zależna od ilości cieczy. Stała część to wyraz wolny, a masa jednego litra — współczynnik przy $x$.","Wzór: masa pojemnika + masa cieczy, czyli $f(x)=6{,}5+1{,}03x$.","Im więcej cieczy, tym większa masa — funkcja jest rosnąca, więc największa wartość jest dla największego $x$, czyli $x=10$ (pełny pojemnik).","$f(10)=6{,}5+1{,}03\\cdot 10=6{,}5+10{,}3=16{,}8$.","Odpowiedź: $16{,}8$."],"2408-11.3":["Pomysł: masa całkowita = masa stała (pusty pojemnik) + masa zależna od ilości cieczy. Stała część to wyraz wolny, a masa jednego litra — współczynnik przy $x$.","Masa całkowita = masa pustego pojemnika (stała, nie zależy od $x$) + masa cieczy.","$x$ litrów cieczy waży $1{,}03\\cdot x$ kg.","$f(x)=1{,}03x+6{,}5$ — współczynnik przy $x$ to masa litra, wyraz wolny to masa pojemnika.","Odpowiedź: $f(x)=1{,}03x+6{,}5$."],"2605-13.2":["Pomysł: $b$ odczytujemy z przecięcia z osią $Oy$, a znak $a$ z kierunku wykresu: rośnie — $a>0$, maleje — $a<0$.","Tangens kąta nachylenia prostej do osi $Ox$ to jej współczynnik kierunkowy $a$.","Z rysunku odczytujemy dwa punkty prostej (np. przecięcia z osiami) i liczymy: o ile zmienia się $y$, gdy $x$ zmienia się o określoną wartość — $a=\\frac{\\Delta y}{\\Delta x}$.","$\\operatorname{tg}\\alpha=-\\frac{3}{2}$.","Odpowiedź: $\\left(-\\frac{3}{2}\\right)$."],"2605-13.1":["Pomysł: $b$ odczytujemy z przecięcia z osią $Oy$, a znak $a$ z kierunku wykresu: rośnie — $a>0$, maleje — $a<0$.","Znak $a$: czytamy wykres od lewej do prawej — prosta maleje, więc $a<0$.","$b$ to wartość dla $x=0$, czyli miejsce przecięcia z osią $Oy$: $(0, 3)$, więc $b>0$.","Odpowiedź: $a<0\\ \\text{i}\\ b>0$."],"2306-11":["Pomysł: o tym, czy funkcja liniowa rośnie, maleje, ma miejsce zerowe lub jest równoległa do innej, decyduje współczynnik przy $x$. Zapisujemy warunek na ten współczynnik i rozwiązujemy.","Dwie proste nie mają punktów wspólnych, gdy są równoległe (i różne) — mają wtedy równe współczynniki kierunkowe.","Współczynnik prostej $f$ to $2m+3$, prostej $g$ to $-1$: $2m+3=-1$.","$2m=-4$, więc $m=-2$. (Wyrazy wolne są różne, więc proste się nie pokrywają.)","Odpowiedź: $m=-2$."],"2405-12":["Pomysł: o tym, czy funkcja liniowa rośnie, maleje, ma miejsce zerowe lub jest równoległa do innej, decyduje współczynnik przy $x$. Zapisujemy warunek na ten współczynnik i rozwiązujemy.","Funkcja liniowa jest malejąca, gdy współczynnik przy $x$ jest ujemny: $-2k+3<0$.","Przenosimy: $-2k<-3$.","Dzielimy przez $-2$ — liczba ujemna, więc <b>zmieniamy zwrot</b>: $k>\\frac{3}{2}$.","Odpowiedź: $\\left(\\frac{3}{2}, +\\infty\\right)$."],"2505-13":["Pomysł: o tym, czy funkcja liniowa rośnie, maleje, ma miejsce zerowe lub jest równoległa do innej, decyduje współczynnik przy $x$. Zapisujemy warunek na ten współczynnik i rozwiązujemy.","Funkcja liniowa $ax+b$ ma miejsce zerowe zawsze, gdy $a\\neq0$ (wtedy $x=-\\frac ba$).","Brak miejsca zerowego jest możliwy tylko, gdy współczynnik przy $x$ jest zerem: $3-m=0$, czyli $m=3$.","Wtedy $f(x)=-4$ — funkcja stała różna od zera, więc rzeczywiście nie ma miejsc zerowych.","Odpowiedź: $3$."],"2506-11":["Pomysł: o tym, czy funkcja liniowa rośnie, maleje, ma miejsce zerowe lub jest równoległa do innej, decyduje współczynnik przy $x$. Zapisujemy warunek na ten współczynnik i rozwiązujemy.","Szukamy miejsca zerowego: $f(x)=0\\iff \\frac{1}{2}x-k=0\\iff \\frac{1}{2}x=k$.","Mnożymy obie strony przez $2$: miejsce zerowe to $x=2k$.","Warunek z treści: $2k>2$, czyli po podzieleniu przez $2$: $k>1$.","Odpowiedź: $\\left(1, +\\infty\\right)$."],"2406-13":["Pomysł: o tym, czy funkcja liniowa rośnie, maleje, ma miejsce zerowe lub jest równoległa do innej, decyduje współczynnik przy $x$. Zapisujemy warunek na ten współczynnik i rozwiązujemy.","„Liczba $2$ jest miejscem zerowym” oznacza $f(2)=0$.","$(3-m)\\cdot 2+4=0$, więc $(3-m)\\cdot 2=-4$, czyli $3-m=-2$, więc $m=3-(-2)=5$.","Odpowiedź: $5$."],"2606-10":["Pomysł: we wzorze $f(x)=ax+b$: znak $a$ mówi o monotoniczności, $b$ to punkt przecięcia z osią $Oy$, a miejsce zerowe obliczamy z $ax+b=0$.","Współczynnik $a=3$ jest dodatni.","$f(0)=-4$."],"2408-10":["Pomysł: współczynnik kierunkowy $a$ to tangens kąta nachylenia prostej do osi $Ox$. Z tangensa odczytujemy kąt (albo inne funkcje tego kąta).","Współczynnik kierunkowy prostej to tangens kąta nachylenia do osi $Ox$: $\\operatorname{tg}\\alpha=\\frac{\\sqrt3}{3}$.","Z tablic: tangens równy $\\frac{\\sqrt3}{3}$ ma kąt $30^\\circ$.","$\\sin30^\\circ=\\frac12$.","Odpowiedź: $\\frac12$."],"2405-13":["Pomysł: wzór $y=ax+b$ ma dwie niewiadome, więc potrzebujemy dwóch informacji (dwóch punktów albo punktu i współczynnika). Każdą zamieniamy na równanie.","Najpierw miejsce zerowe funkcji $f$: $3x+6=0\\iff 3x=-6\\iff x=-2$.","To samo miejsce zerowe ma $g$, więc $g(-2)=0$: $a\\cdot (-2)+7=0$.","Przenosimy $7$: $-2a=-7$, a potem dzielimy przez $-2$: $a=\\frac{-7}{-2}=\\frac{7}{2}$.","Odpowiedź: $\\frac{7}{2}$."],"2506-12":["Pomysł: wzór $y=ax+b$ ma dwie niewiadome, więc potrzebujemy dwóch informacji (dwóch punktów albo punktu i współczynnika). Każdą zamieniamy na równanie.","Przesunięcie wykresu o $1$ w prawo to zamiana $x$ na $x-1$: $g(x)=f(x-1)$.","$g(x)=5(x-1)$ — mnożymy $5$ przez każdy wyraz w nawiasie.","$g(x)=5x-5$.","Odpowiedź: $g(x)=5x-5$."],"2606-7":["Pomysł: odczytujemy miejsca zerowe z postaci iloczynowej, szkicujemy parabolę (współczynnik przy $x^2$ mówi, czy ramiona idą w górę, czy w dół) i odczytujemy, gdzie wykres jest nad/pod osią.","Miejsca zerowe odczytujemy z nawiasów: $x+3=0\\Rightarrow x=-3$ oraz $x-2=0\\Rightarrow x=2$.","Liczba przed nawiasami to $-2$ — ujemna, więc ramiona paraboli idą w dół.","Szkicujemy parabolę przez $-3$ i $2$: tu potrzebna część jest między miejscami zerowymi. Nierówność ostra, więc końce nie należą: $(-3, 2)$.","Odpowiedź: $(-3, 2)$."],"2608-13.2":["Pomysł: postać kanoniczną zamieniamy na ogólną, rozwijając kwadrat ze wzoru skróconego mnożenia i mnożąc przez współczynnik $a$ — każdy wyraz z osobna.","Rozwijamy kwadrat ze wzoru $(x\\pm b)^2=x^2\\pm2bx+b^2$: $(x-2)^2=x^2-4x+4$.","Mnożymy każdy wyraz nawiasu przez $2$: $2\\cdot x^2=2x^2$, $\\ 2\\cdot(-4x)=-8x$, $\\ 2\\cdot 4=8$.","Dodajemy $4$ do wyrazu wolnego: $8+4=12$.","$f(x)=2x^{2}-8x+12$.","Odpowiedź: $f(x)=2x^{2}-8x+12$."],"2209-13.1":["Pomysł: z postaci kanonicznej $a(x-p)^2+q$ od razu widać wierzchołek $(p, q)$ i kierunek ramion (znak $a$). Każde stwierdzenie sprawdzamy osobno.","Wierzchołek leży po drugiej stronie osi $Ox$ niż ramiona — są dwa miejsca zerowe.","Punkt przecięcia z osią $Oy$ to $(0, f(0))$. Podstawiamy $x=0$: $f(0)=-1\\cdot(0-1)^2+2=-1\\cdot 1+2=-1+2=1$."],"2405-14.1":["Pomysł: z rysunku odczytujemy wierzchołek $(p, q)$ i miejsca zerowe. Oś symetrii to pionowa prosta $x=p$, a ramiona paraboli mówią, czy $q$ jest wartością najmniejszą, czy największą.","Z rysunku odczytujemy miejsca zerowe (przecięcia z osią $Ox$): $-4$ i $0$.","Nierówność $f(x)\\geq 0$ to pytanie: gdzie wykres leży nad osią $Ox$ (albo na niej)? Ramiona w dół, więc między miejscami zerowymi.","Zbiór rozwiązań (z końcami, bo nierówność nieostra): $[-4, 0]$.","Odpowiedź: $[-4, 0]$."],"2505-12.3":["Pomysł: z rysunku odczytujemy wierzchołek $(p, q)$ i miejsca zerowe. Oś symetrii to pionowa prosta $x=p$, a ramiona paraboli mówią, czy $q$ jest wartością najmniejszą, czy największą.","Miejsca zerowe to pierwsze współrzędne punktów, w których parabola przecina oś $Ox$. Z rysunku: $x_1=-2$, $x_2=0$.","Suma: $-2+0=-2$.","Sprawdzenie: wierzchołek leży dokładnie w połowie między miejscami zerowymi, więc $x_1+x_2=2p=2\\cdot (-1)=-2$.","Odpowiedź: $\\left(-2\\right)$."],"2308-15":["Pomysł: zbiór wartości funkcji kwadratowej zależy od wierzchołka i kierunku ramion: przy ramionach w górę to $[q, +\\infty)$, w dół — $(-\\infty, q]$.","Zbiór $(-\\infty, q]$ mają funkcje $a(x-p)^2+q$ z $a<0$ i $q=2$ — $p$ może być dowolne."],"2508-14.1":["Pomysł: parabola jest symetryczna względem prostej $x=p$. Punkty o tej samej wartości (np. dwa miejsca zerowe) leżą w równych odległościach od $p$, więc $p$ jest ich średnią.","Oś symetrii $x=1$ leży w połowie między miejscami zerowymi: $\\frac{-4+x_2}{2}=1$.","Mnożymy przez $2$: $-4+x_2=2$, więc $x_2=2-(-4)=6$.","Postać iloczynowa $a(x-x_1)(x-x_2)$, a współczynnik przy $x^2$ to $0.5$: $f(x)=\\frac12(x+4)(x-6)$.","Odpowiedź: $f(x)=\\frac12(x+4)(x-6)$."],"2606-11":["Pomysł: „liczba $x_0$ jest miejscem zerowym” znaczy $f(x_0)=0$. Podstawiamy $x_0$ i rozwiązujemy równanie z niewiadomą $k$.","„Liczba $2$ jest miejscem zerowym” oznacza $f(2)=0$.","Podstawiamy $x=2$: $2\\cdot 2^2-k\\cdot 2+6=0$.","$2^2=4$, więc $2\\cdot 4=8$; a $-k\\cdot 2=-2k$. Równanie: $8-2k+6=0$.","Liczby razem: $8+6=14$, więc $-2k=-14$.","Dzielimy przez $-2$: $k=7$.","Odpowiedź: $7$."],"2306-14":["Pomysł: znak $a$ mówi o ramionach (w górę/w dół), $c=f(0)$ — gdzie wykres przecina oś $Oy$, a znak $b$ (razem z $a$) — po której stronie osi $Oy$ leży wierzchołek ($p=-\\frac{b}{2a}$).","$a<0$, więc ramiona paraboli są skierowane w dół.","$c=f(0)=1$ — wykres przecina oś $Oy$ w punkcie $(0, 1)$.","Pierwsza współrzędna wierzchołka $p=-\\frac{b}{2a}$: $a$ i $b$ mają różne znaki, więc $p$ jest dodatnie (wierzchołek na prawo od osi $Oy$)."],"2305-4":["Pomysł: logarytmy o tej samej podstawie łączymy w jeden: suma to logarytm iloczynu, różnica — logarytm ilorazu. Potem pytamy, do jakiej potęgi podnieść podstawę.","Suma logarytmów to logarytm iloczynu: $\\log_{9}\\left(27\\cdot3\\right)$.","Liczymy w nawiasie: $27\\cdot 3=81$.","Pytamy: do jakiej potęgi $c$ podnieść $9$, aby otrzymać $81$?","Obie liczby zapisujemy jako potęgi $3$: $9=3^{2}$, $\\ 81=3^{4}$.","$\\left(3^{2}\\right)^c=3^{4}$, czyli $2c=4$, więc $c=\\frac{4}{2}=2$.","Odpowiedź: $2$."],"2505-3":["Pomysł: logarytmy o tej samej podstawie łączymy w jeden: suma to logarytm iloczynu, różnica — logarytm ilorazu. Potem pytamy, do jakiej potęgi podnieść podstawę.","Żadnego z tych logarytmów nie policzymy osobno (108 i 2 nie są potęgami liczby $3$). Dlatego łączymy je w jeden.","Najpierw liczba przed logarytmem wchodzi do wykładnika: $2\\log_{3}2=\\log_{3}2^2=\\log_{3}4$.","Różnica logarytmów o tej samej podstawie to logarytm ilorazu: $\\log_{3}\\frac{108}{4}=\\log_{3}27$.","$27=3^{3}$, więc wynik to $3$.","Odpowiedź: $3$."],"2508-4":["Pomysł: logarytmy o tej samej podstawie łączymy w jeden: suma to logarytm iloczynu, różnica — logarytm ilorazu. Potem pytamy, do jakiej potęgi podnieść podstawę.","Żadnego z tych logarytmów nie policzymy osobno (2 i 18 nie są potęgami liczby $3$). Dlatego łączymy je w jeden.","Różnica logarytmów o tej samej podstawie to logarytm ilorazu: $\\log_{3}\\frac{2}{18}=\\log_{3}\\frac{1}{9}$.","$\\frac{1}{9}=3^{-2}$, więc wynik to $-2$.","Odpowiedź: $\\left(-2\\right)$."],"2608-3":["Pomysł: logarytmy o tej samej podstawie łączymy w jeden: suma to logarytm iloczynu, różnica — logarytm ilorazu. Potem pytamy, do jakiej potęgi podnieść podstawę.","Wszystkie logarytmy mają tę samą podstawę $8$, więc możemy je połączyć w jeden: dodawanie zamienia się w mnożenie, odejmowanie w dzielenie.","$\\log_{8}4+\\log_{8}32-\\log_{8}2=\\log_{8}\\frac{4\\cdot 32}{2}=\\log_{8}64$.","Pytamy: do jakiej potęgi podnieść $8$, aby otrzymać $64$? Zapisz obie liczby jako potęgi $2$: $8=2^{3}$, $64=2^{6}$. Odpowiedź: $2$, bo $8^{2}=64$.","Odpowiedź: $2$."],"2405-4":["Pomysł: logarytm to wykładnik. Zapisujemy liczbę logarytmowaną i podstawę jako potęgi tej samej liczby i porównujemy wykładniki.","Szukamy liczby $c$, dla której $\\left(\\sqrt{3}\\right)^c=9$.","$\\sqrt{3}=3^{\\frac12}$, a $9=3^{2}$. Więc $\\left(3^{\\frac12}\\right)^c=3^{2}$, czyli $\\frac{c}{2}=2$, więc $c=4$.","Odpowiedź: $4$."],"2606-3":["Pomysł: logarytm to wykładnik. Zapisujemy liczbę logarytmowaną i podstawę jako potęgi tej samej liczby i porównujemy wykładniki.","Najpierw zapisujemy liczbę pod pierwiastkiem jako potęgę podstawy: $25=5^{2}$.","Pierwiastek stopnia $3$ to wykładnik $\\frac1{3}$: $\\sqrt[3]{5^{2}}=5^{\\frac{2}{3}}$.","Logarytm o podstawie $5$ z potęgi $5$ to po prostu jej wykładnik: $\\log_{5}5^{\\frac{2}{3}}=\\frac{2}{3}$.","Odpowiedź: $\\frac{2}{3}$."],"2405-15":["Pomysł: najpewniej wypisać kilka pierwszych wyrazów i na nich sprawdzić każde stwierdzenie.","$(-1)^n$ to $1$ dla parzystych $n$ i $-1$ dla nieparzystych — podstawiamy kolejne $n$.","$a_{2}=(-1)^{2}\\cdot(2-5)=-3$.","$a_{7}=-2$, $a_{8}=3$."],"2406-16.1":["Pomysł: wyrazy liczymy ze wzoru po kolei i dodajemy. Gdy dana jest suma $S_n$, to $a_n=S_n-S_{n-1}$ — różnica dwóch kolejnych sum to jeden wyraz.","$(-1)^{n+1}$ to $1$ dla nieparzystych $n$ i $-1$ dla parzystych, więc wyrazy to na zmianę: $2+5=7$ oraz $-2+5=3$.","Grupujemy w pary $(a_1+a_2), (a_3+a_4), \\ldots$ — każda para daje $7+3=10$.","$10$ wyrazów to $5$ par: $5\\cdot 10=50$.","Odpowiedź: $50$."],"2506-14.1":["Pomysł: wyrazy liczymy ze wzoru po kolei i dodajemy. Gdy dana jest suma $S_n$, to $a_n=S_n-S_{n-1}$ — różnica dwóch kolejnych sum to jeden wyraz.","Liczymy trzy pierwsze wyrazy ze wzoru: $a_1=3\\cdot1^2-3\\cdot1=0$, $a_2=3\\cdot2^2-3\\cdot2=6$, $a_3=3\\cdot3^2-3\\cdot3=18$.","Dodajemy: $0+6+18=24$.","Odpowiedź: $24$."],"2308-17":["Pomysł: w ciągu geometrycznym każdy krok to mnożenie przez iloraz $q$: $a_n=a_1\\cdot q^{n-1}$.","Wyrazy ciągu geometrycznego: $a_n=a_1\\cdot q^{n-1}$ — każdy następny to poprzedni razy $\\frac{1}{2}$.","Iloraz dodatni i $a_1>0$ — wszystkie wyrazy są dodatnie.","$a_2=64$, $a_3=32$, więc $a_3-a_2=32-64=-32$."],"2508-17":["Pomysł: w ciągu geometrycznym każdy krok to mnożenie przez iloraz $q$: $a_n=a_1\\cdot q^{n-1}$.","Wyraz $a_{6}$ powstaje z $a_{3}$ przez $3$-krotne mnożenie przez $q$: $a_{6}=a_{3}\\cdot q^{3}$.","Podstawiamy do warunku: $a_{3}=-8\\cdot a_{3}\\cdot q^{3}$.","Dzielimy obie strony przez $a_{3}$: $1=-8\\cdot q^{3}$, czyli $q^{3}=\\frac{1}{-8}=-\\frac{1}{8}$.","$q=-\\frac{1}{2}$, bo $\\left(-\\frac{1}{2}\\right)\\cdot \\left(-\\frac{1}{2}\\right)\\cdot \\left(-\\frac{1}{2}\\right)=-\\frac{1}{8}$.","Odpowiedź: $\\left(-\\frac{1}{2}\\right)$."],"2605-17":["Pomysł: w ciągu geometrycznym iloczyn wyrazów „symetrycznych” jest stały: $a_i\\cdot a_j$ zależy tylko od sumy indeksów $i+j$.","Zapisujemy wyrazy przez $a_1$ i $q$: $a_{3}\\cdot a_{6}=a_1q^{2}\\cdot a_1q^{5}=a_1^2q^{7}$.","Tak samo: $a_{2}\\cdot a_{7}=a_1q^{1}\\cdot a_1q^{6}=a_1^2q^{7}$ — ten sam wynik, bo suma indeksów jest taka sama ($9$).","Zatem $a_{2}\\cdot a_{7}=18$.","Odpowiedź: $18$."],"2305-18":["Pomysł: dla punktu $P=(x, y)$ na ramieniu kąta: $\\operatorname{tg}\\alpha=\\frac yx$, $\\sin\\alpha=\\frac yr$, $\\cos\\alpha=\\frac xr$, gdzie $r=|OP|=\\sqrt{x^2+y^2}$.","Odczytujemy współrzędne punktu na ramieniu kąta: $x=-3$, $y=1$.","Tangens kąta w układzie współrzędnych: $\\operatorname{tg}\\alpha=\\frac{y}{x}$ (druga współrzędna przez pierwszą).","$\\operatorname{tg}\\alpha=\\frac{1}{-3}=-\\frac{1}{3}$ — ujemny, bo punkt leży w II ćwiartce (kąt rozwarty).","Odpowiedź: $\\left(-\\frac{1}{3}\\right)$."],"2405-18":["Pomysł: dla punktu $P=(x, y)$ na ramieniu kąta: $\\operatorname{tg}\\alpha=\\frac yx$, $\\sin\\alpha=\\frac yr$, $\\cos\\alpha=\\frac xr$, gdzie $r=|OP|=\\sqrt{x^2+y^2}$.","Kąt rozwarty: punkt na ramieniu kąta ma $x<0$ i $y>0$, więc $\\sin\\alpha>0$, $\\cos\\alpha<0$ — iloczyn $\\sin\\alpha\\cdot\\cos\\alpha<0$.","$\\operatorname{tg}\\alpha=\\frac{\\sin\\alpha}{\\cos\\alpha}=-3$; mnożymy obie strony przez $\\cos\\alpha$: $\\sin\\alpha=-3\\cos\\alpha$."],"inf-39":["Pomysł: dorysowujemy trójkąt prostokątny o bokach z danego ułamka, trzeci bok liczymy z Pitagorasa (albo z jedynki $\\sin^2\\alpha+\\cos^2\\alpha=1$) i odczytujemy szukaną funkcję.","Z jedynki: $\\cos^2\\alpha=1-\\sin^2\\alpha=1-\\frac{16}{25}=\\frac{25}{25}-\\frac{16}{25}=\\frac{9}{25}$.","Stąd $\\cos\\alpha=\\frac{3}{5}$ albo $\\cos\\alpha=-\\frac{3}{5}$.","Kąt rozwarty (między $90^\\circ$ a $180^\\circ$) ma ujemny cosinus, więc $\\cos\\alpha=-\\frac{3}{5}$.","Odpowiedź: $\\left(-\\frac{3}{5}\\right)$."],"2408-16":["Pomysł: dorysowujemy trójkąt prostokątny o bokach z danego ułamka, trzeci bok liczymy z Pitagorasa (albo z jedynki $\\sin^2\\alpha+\\cos^2\\alpha=1$) i odczytujemy szukaną funkcję.","Najpierw sinus z jedynki trygonometrycznej: $\\sin^2\\alpha=1-\\cos^2\\alpha=1-\\frac{576}{625}=\\frac{625}{625}-\\frac{576}{625}=\\frac{49}{625}$.","Kąt ostry, więc $\\sin\\alpha=\\sqrt{\\frac{49}{625}}=\\frac{7}{25}$.","Tangens to iloraz: $\\operatorname{tg}\\alpha=\\frac{\\sin\\alpha}{\\cos\\alpha}=\\frac{\\frac{7}{25}}{\\frac{24}{25}}$.","Mianowniki $25$ się skracają: $\\operatorname{tg}\\alpha=\\frac{7}{24}$.","Odpowiedź: $\\frac{7}{24}$."],"2508-19":["Pomysł: dorysowujemy trójkąt prostokątny o bokach z danego ułamka, trzeci bok liczymy z Pitagorasa (albo z jedynki $\\sin^2\\alpha+\\cos^2\\alpha=1$) i odczytujemy szukaną funkcję.","Najpierw sinus z jedynki trygonometrycznej: $\\sin^2\\alpha=1-\\cos^2\\alpha=1-\\frac{25}{169}=\\frac{169}{169}-\\frac{25}{169}=\\frac{144}{169}$.","Kąt ostry, więc $\\sin\\alpha=\\sqrt{\\frac{144}{169}}=\\frac{12}{13}$.","Tangens to iloraz: $\\operatorname{tg}\\alpha=\\frac{\\sin\\alpha}{\\cos\\alpha}=\\frac{\\frac{12}{13}}{\\frac{5}{13}}$.","Mianowniki $13$ się skracają: $\\operatorname{tg}\\alpha=\\frac{12}{5}$.","Odpowiedź: $\\frac{12}{5}$."],"2606-21":["Pomysł: dorysowujemy trójkąt prostokątny o bokach z danego ułamka, trzeci bok liczymy z Pitagorasa (albo z jedynki $\\sin^2\\alpha+\\cos^2\\alpha=1$) i odczytujemy szukaną funkcję.","Z jedynki: $\\cos^2\\alpha=1-\\sin^2\\alpha=1-\\frac{9}{25}=\\frac{25}{25}-\\frac{9}{25}=\\frac{16}{25}$.","Stąd $\\cos\\alpha=\\frac{4}{5}$ albo $\\cos\\alpha=-\\frac{4}{5}$.","Kąt rozwarty (między $90^\\circ$ a $180^\\circ$) ma ujemny cosinus, więc $\\cos\\alpha=-\\frac{4}{5}$.","Odpowiedź: $\\left(-\\frac{4}{5}\\right)$."],"2506-18":["Pomysł: zaznaczamy kąt i nazywamy boki względem niego: przyprostokątna naprzeciw, przyprostokątna przy kącie, przeciwprostokątna. Sinus = naprzeciw : przeciwprostokątna, cosinus = przy : przeciwprostokątna, tangens = naprzeciw : przy.","Wygodnie przyjąć konkretne długości: przeciwprostokątna $7$, przyprostokątna naprzeciw $\\alpha$ równa $4$; druga przyprostokątna: $\\sqrt{7^2-4^2}=\\sqrt{33}$.","$\\cos\\alpha\\neq1-\\sin\\alpha$. Z jedynki: $\\cos^2\\alpha=1-\\frac{16}{49}=\\frac{33}{49}$, więc $\\cos\\alpha=\\frac{\\sqrt{33}}{7}$.","$\\cos^2\\alpha=1-\\sin^2\\alpha=\\frac{33}{49}$."],"2406-20":["Pomysł: zaznaczamy kąt i nazywamy boki względem niego: przyprostokątna naprzeciw, przyprostokątna przy kącie, przeciwprostokątna. Sinus = naprzeciw : przeciwprostokątna, cosinus = przy : przeciwprostokątna, tangens = naprzeciw : przy.","Spuszczamy wysokość z $C$ na $AB$ — powstaje trójkąt prostokątny o przyprostokątnych: wysokość $\\sqrt3$ i odcinek $8-5=3$.","$\\operatorname{tg}\\angle ABC=\\frac{\\sqrt3}{3}=\\frac{\\sqrt3}{3}$.","Taki tangens ma kąt $30^\\circ$.","Odpowiedź: $30^\\circ$."],"2508-20":["Pomysł: wartości funkcji dla kątów $30^\\circ$, $45^\\circ$, $60^\\circ$ bierzemy z tablic, podstawiamy i liczymy.","Z tablic: $\\sin30^\\circ=\\frac12$, $\\cos60^\\circ=\\frac12$, $\\sin60^\\circ=\\frac{\\sqrt3}{2}$, $\\cos30^\\circ=\\frac{\\sqrt3}{2}$.","Iloczyny: $\\frac12\\cdot \\frac12=\\frac14$ oraz $\\frac{\\sqrt3}{2}\\cdot \\frac{\\sqrt3}{2}=\\frac34$.","Suma: $\\frac14+\\frac34=1$.","Odpowiedź: $1$."],"2305-19":["Pomysł: szukamy wspólnego czynnika do wyłączenia przed nawias — w nawiasie zwykle pojawia się jedynka trygonometryczna $\\sin^2\\alpha+\\cos^2\\alpha=1$.","Oba składniki zawierają $\\sin^2\\alpha$, więc wyłączamy go przed nawias: $\\sin^2\\alpha\\,(\\sin^2\\alpha+\\cos^2\\alpha)$.","W nawiasie jest jedynka trygonometryczna: $\\sin^2\\alpha+\\cos^2\\alpha=1$.","Zostaje $\\sin^2\\alpha\\cdot 1=\\sin^2\\alpha$.","Odpowiedź: $\\sin^2\\alpha$."],"2306-19":["Pomysł: szukamy wspólnego czynnika do wyłączenia przed nawias — w nawiasie zwykle pojawia się jedynka trygonometryczna $\\sin^2\\alpha+\\cos^2\\alpha=1$.","Oba składniki zawierają $\\cos\\alpha$ — wyłączamy go przed nawias: $\\cos\\alpha\\,(1-\\sin^2\\alpha)$.","Z jedynki trygonometrycznej $1-\\sin^2\\alpha=\\cos^2\\alpha$.","$\\cos\\alpha\\cdot\\cos^2\\alpha=\\cos^3\\alpha$.","Odpowiedź: $\\cos^3\\alpha$."],"2405-19":["Pomysł: szukamy wspólnego czynnika do wyłączenia przed nawias — w nawiasie zwykle pojawia się jedynka trygonometryczna $\\sin^2\\alpha+\\cos^2\\alpha=1$.","Oba składniki zawierają $\\sin20^\\circ$ — wyłączamy go przed nawias: $\\sin20^\\circ\\,(\\sin^220^\\circ+\\cos^220^\\circ)$.","W nawiasie jest jedynka trygonometryczna: $\\sin^220^\\circ+\\cos^220^\\circ=1$.","Zostaje $\\sin20^\\circ\\cdot1=\\sin20^\\circ$.","Odpowiedź: $\\sin20^\\circ$."],"2406-19":["Pomysł: szukamy wspólnego czynnika do wyłączenia przed nawias — w nawiasie zwykle pojawia się jedynka trygonometryczna $\\sin^2\\alpha+\\cos^2\\alpha=1$.","Z jedynki trygonometrycznej: $\\cos^227^\\circ=1-\\sin^227^\\circ$.","Podstawiamy: $1+\\cos^227^\\circ=1+1-\\sin^227^\\circ=2-\\sin^227^\\circ$.","Odpowiedź: $2-\\sin^227^\\circ$."],"2506-17":["Pomysł: szukamy wspólnego czynnika do wyłączenia przed nawias — w nawiasie zwykle pojawia się jedynka trygonometryczna $\\sin^2\\alpha+\\cos^2\\alpha=1$.","Najpierw licznik: wyłączamy $\\sin25^\\circ$ przed nawias — $\\sin25^\\circ\\,(\\sin^225^\\circ+\\cos^225^\\circ)=\\sin25^\\circ\\cdot1$.","Ułamek to więc $\\frac{\\sin25^\\circ}{\\cos25^\\circ}$.","A to z definicji tangens: $\\operatorname{tg}25^\\circ$.","Odpowiedź: $\\operatorname{tg}25^\\circ$."],"2505-17":["Pomysł: przekształcamy warunek tak, aby został tylko stosunek $\\frac{\\sin\\alpha}{\\cos\\alpha}=\\operatorname{tg}\\alpha$ (albo samo $\\cos\\alpha$), korzystając z jedynki trygonometrycznej.","Zamieniamy tangens na iloraz: $\\sqrt3\\cdot\\frac{\\sin\\alpha}{\\cos\\alpha}=2\\sin\\alpha$.","Kąt ostry, więc $\\sin\\alpha\\neq0$ — dzielimy obie strony przez $\\sin\\alpha$: $\\frac{\\sqrt3}{\\cos\\alpha}=2$.","Stąd $\\cos\\alpha=\\frac{\\sqrt3}{2}$.","Odpowiedź: $\\frac{\\sqrt3}{2}$."],"2605-23":["Pomysł: przekształcamy warunek tak, aby został tylko stosunek $\\frac{\\sin\\alpha}{\\cos\\alpha}=\\operatorname{tg}\\alpha$ (albo samo $\\cos\\alpha$), korzystając z jedynki trygonometrycznej.","Rozbijamy ułamek na dwa (wspólny mianownik): $\\frac{3\\sin\\alpha}{4\\cos\\alpha}+\\frac{4\\cos\\alpha}{4\\cos\\alpha}=6$.","Drugi ułamek to $1$, a w pierwszym $\\frac{\\sin\\alpha}{\\cos\\alpha}=\\operatorname{tg}\\alpha$: $\\frac{3}{4}\\operatorname{tg}\\alpha+1=6$.","$\\frac{3}{4}\\operatorname{tg}\\alpha=5$, więc $\\operatorname{tg}\\alpha=5\\cdot\\frac{4}{3}=\\frac{20}{3}$.","Odpowiedź: $\\frac{20}{3}$."],"2606-17":["Pomysł: $\\sin\\alpha=\\frac{\\text{przyprostokątna naprzeciw}}{\\text{przeciwprostokątna}}$ — stąd od razu przyprostokątna leżąca naprzeciw kąta.","$\\sin\\alpha=\\frac1{4}<\\frac12$, więc $\\alpha$ jest mniejszy niż $30^\\circ$ — $\\alpha$ to najmniejszy kąt, a naprzeciw najmniejszego kąta leży najkrótsza przyprostokątna.","Z definicji sinusa: $\\sin\\alpha=\\frac{a}{c}$, więc $a=c\\cdot\\sin\\alpha$.","$a=8\\cdot\\frac1{4}=\\frac{8}{4}=8:4=2$.","Odpowiedź: $2$."],"2405-20":["Pomysł: dwusieczna dzieli przeciwległy bok w takim stosunku, w jakim są boki przy niej: $\\frac{|AD|}{|DB|}=\\frac{|AC|}{|BC|}$.","Twierdzenie o dwusiecznej: dwusieczna dzieli przeciwległy bok w stosunku długości boków przyległych: $\\frac{|KN|}{|NL|}=\\frac{|KM|}{|LM|}$, czyli $\\frac{c}{d}=\\frac{a}{b}$.","Mnożymy „na krzyż”: $a\\cdot d=b\\cdot c$.","Odpowiedź: $a\\cdot d=b\\cdot c$."],"inf-42":["Pomysł: środek ciężkości dzieli każdą środkową w stosunku $2:1$, licząc od wierzchołka.","Część środkowej przy wierzchołku jest dwa razy dłuższa niż część przy boku.","$|SA|=10$ to dwie części, więc jedna część to $10:2=5$.","Środkowa ma trzy takie części: $3\\cdot 5=15$.","Odpowiedź: $15$."],"2606-19":["Pomysł: proste równoległe tworzą trójkąty podobne — odpowiadające odcinki są proporcjonalne. Układamy proporcję i rozwiązujemy.","Proste $k\\parallel l$, więc trójkąty $ABC$ i $ADE$ są podobne (twierdzenie Talesa) — odpowiadające odcinki są proporcjonalne.","$|AD|=|AB|+|BD|=6+2=8$. Proporcja: $\\frac{|DE|}{|BC|}=\\frac{|AD|}{|AB|}$, czyli $\\frac{|DE|}{4}=\\frac{8}{6}$.","Mnożymy obie strony przez $4$: $|DE|=4\\cdot \\frac{4}{3}=\\frac{4\\cdot 4}{1\\cdot 3}=\\frac{16}{3}$.","Odpowiedź: $\\frac{16}{3}$."],"2608-21":["Pomysł: w figurach podobnych w skali $k$ długości (i obwody) mnożą się przez $k$, a pola — przez $k^2$.","Obwód danego trójkąta: $4+8+10=22$.","Obwody figur podobnych mają się jak skala: $k=\\frac{44}{22}=2$.","Najkrótszy bok odpowiada najkrótszemu bokowi danego trójkąta: $4\\cdot 2=8$.","Odpowiedź: $8$."],"2505-20":["Pomysł: w trójkątach podobnych stosunki odpowiadających boków są równe. Trzeba starannie dobrać, który bok odpowiada któremu.","Trójkąty $ABC$ i $BDA$ są podobne, a kolejność liter mówi, które wierzchołki sobie odpowiadają: $A\\leftrightarrow B$, $B\\leftrightarrow D$, $C\\leftrightarrow A$.","Odpowiadające boki: $BD\\leftrightarrow AB$ oraz $AB\\leftrightarrow AC$, więc $\\frac{|BD|}{|AB|}=\\frac{|AB|}{|AC|}$, czyli $\\frac{|BD|}{3}=\\frac{3}{4}$.","$|BD|=\\frac{3\\cdot 3}{4}=\\frac{9}{4}=2{,}25$.","Odpowiedź: $2{,}25$."],"2405-21":["Pomysł: pole równoległoboku (i rombu) to iloczyn dwóch boków razy sinus kąta między nimi; pole rombu to też połowa iloczynu przekątnych.","Pole równoległoboku: $P=ab\\sin\\alpha$, gdzie $\\alpha$ — kąt między bokami (ostry lub rozwarty — sinus jest ten sam, bo $\\sin120^\\circ=\\sin60^\\circ$).","$\\sin60^\\circ=\\frac{\\sqrt3}{2}$.","$P=2\\cdot 6\\cdot \\frac{\\sqrt3}{2}=12\\cdot \\frac{\\sqrt3}{2}=\\frac{12\\sqrt3}{2}=6\\sqrt3$.","Odpowiedź: $6\\sqrt3$."],"2508-23":["Pomysł: przekątne trapezu tworzą dwa trójkąty podobne (przy podstawach) w skali równej stosunkowi podstaw; trójkąty o wspólnej podstawie i tej samej wysokości mają równe pola.","Wspólna podstawa $CD$ i ta sama wysokość trapezu.","$|AE|:|EC|=|AB|:|CD|=2$."],"2305-21":["Pomysł: kąt wpisany jest połową kąta środkowego opartego na tym samym łuku, kąty wpisane oparte na tym samym łuku są równe, a kąt oparty na średnicy jest prosty.","$|OA|=|OC|$ (promienie), więc trójkąt $AOC$ jest równoramienny i kąty przy podstawie są równe: $|\\angle OAC|=|\\angle OCA|=70^\\circ$.","Kąt przy wierzchołku $O$: $|\\angle AOC|=180^\\circ-2\\cdot 70^\\circ=40^\\circ$ — to kąt środkowy oparty na łuku $AC$.","Kąt wpisany $ABC$ oparty na tym samym łuku to połowa: $\\frac{40^\\circ}{2}=20^\\circ$.","Odpowiedź: $20^\\circ$."],"2308-22":["Pomysł: kąt wpisany jest połową kąta środkowego opartego na tym samym łuku, kąty wpisane oparte na tym samym łuku są równe, a kąt oparty na średnicy jest prosty.","Kąt środkowy jest dwa razy większy od wpisanego opartego na tym samym łuku: $\\beta=2\\alpha$.","Z treści: $\\beta=\\alpha+40^\\circ$. Porównujemy: $2\\alpha=\\alpha+40^\\circ$, więc $\\alpha=40^\\circ$.","$\\beta=2\\cdot 40^\\circ=80^\\circ$.","Odpowiedź: $80^\\circ$."],"2405-22":["Pomysł: kąt wpisany jest połową kąta środkowego opartego na tym samym łuku, kąty wpisane oparte na tym samym łuku są równe, a kąt oparty na średnicy jest prosty.","Kąt środkowy $ASB$ jest oparty na tym samym łuku co kąt wpisany $ACB$, więc $|\\angle ASB|=2\\cdot 42^\\circ=84^\\circ$.","$|SA|=|SB|$ (promienie), więc trójkąt $ASB$ jest równoramienny — kąty przy $A$ i $B$ są równe.","Suma kątów w trójkącie to $180^\\circ$: $|\\angle BAS|=\\frac{180^\\circ-84^\\circ}{2}=48^\\circ$.","Odpowiedź: $48^\\circ$."],"2406-21":["Pomysł: kąt wpisany jest połową kąta środkowego opartego na tym samym łuku, kąty wpisane oparte na tym samym łuku są równe, a kąt oparty na średnicy jest prosty.","Łuk stanowiący $\\frac1{5}$ okręgu odpowiada kątowi środkowemu $\\frac1{5}$ kąta pełnego: $\\frac{360^\\circ}{5}=72^\\circ$.","Kąt wpisany oparty na tym łuku to połowa kąta środkowego: $\\frac{72^\\circ}{2}=36^\\circ$.","Odpowiedź: $36^\\circ$."],"2408-19":["Pomysł: kąt wpisany jest połową kąta środkowego opartego na tym samym łuku, kąty wpisane oparte na tym samym łuku są równe, a kąt oparty na średnicy jest prosty.","Punkt $L$ leży na krótszym łuku $KM$, więc kąt $KLM$ „patrzy” na <b>dłuższy</b> łuk $KM$.","Dłuższemu łukowi odpowiada kąt środkowy $360^\\circ-160^\\circ=200^\\circ$.","Kąt wpisany to połowa: $|\\angle KLM|=\\frac{200^\\circ}{2}=100^\\circ$.","Odpowiedź: $100^\\circ$."],"2506-20":["Pomysł: kąt wpisany jest połową kąta środkowego opartego na tym samym łuku, kąty wpisane oparte na tym samym łuku są równe, a kąt oparty na średnicy jest prosty.","Wierzchołki wielokąta foremnego dzielą okrąg na $10$ równych łuków; każdemu odpowiada kąt środkowy $\\frac{360^\\circ}{10}=36^\\circ$.","Łuk $AD$ (bez punktu $G$) składa się z $3$ takich łuków: kąt środkowy $3\\cdot 36^\\circ=108^\\circ$.","Kąt wpisany to połowa: $54^\\circ$.","Odpowiedź: $54^\\circ$."],"2605-22":["Pomysł: w trójkącie prostokątnym środek okręgu opisanego to środek przeciwprostokątnej ($R=\\frac c2$), a promień wpisanego to $r=\\frac{a+b-c}{2}$. W trójkącie równobocznym $R=\\frac{a\\sqrt3}{3}$.","Środek okręgu opisanego na trójkącie równobocznym leży w $\\frac23$ wysokości: $R=\\frac23\\cdot\\frac{a\\sqrt3}{2}=\\frac{a\\sqrt3}{3}$.","Przekształcamy: $a=\\frac{3R}{\\sqrt3}=R\\sqrt3$.","$a=9\\sqrt3\\cdot\\sqrt3=9\\cdot3=27$.","Odpowiedź: $27$."],"2308-21":["Pomysł: wycinek to taka część koła, jaką część kąta pełnego ($360^\\circ$) stanowi jego kąt środkowy. Obwód wycinka = łuk + dwa promienie.","Wycinek o kącie $30^\\circ$ to $\\frac{30}{360}$ koła, więc łuk to taka część obwodu koła $2\\pi r$.","Skracamy ułamek: $\\frac{30}{360}=\\frac{30:30}{360:30}=\\frac{1}{12}$. Obwód całego koła: $2\\pi\\cdot 3=6\\pi$.","Łuk: $\\frac{1}{12}\\cdot 6\\pi=\\frac{1}{2}\\pi$.","Obwód wycinka = łuk + dwa promienie: $\\frac{1}{2}\\pi+2\\cdot 3=\\frac{1}{2}\\pi+6$.","Odpowiedź: $\\frac{1}{2}\\pi+6$."],"2308-26":["Pomysł: okrąg o środku $(a, b)$ i promieniu $r$ ma równanie $(x-a)^2+(y-b)^2=r^2$ — znaki w nawiasach są przeciwne do współrzędnych środka, a po prawej jest $r^2$.","Równanie okręgu o środku $(a, b)$ i promieniu $r$: $(x-a)^2+(y-b)^2=r^2$.","Środek: $(-1, 2)$.","$r=3$, więc $r^2=3^2=9$.","Uwaga na znaki: $x-(-1)$ to $x+1$, a $y-(2)$ to $y-2$. Równanie: $(x+1)^2+(y-2)^2=9$.","Odpowiedź: $(x+1)^2+(y-2)^2=9$."],"2406-23.2":["Pomysł: przy symetrii okręgu zmienia się tylko środek (promień zostaje): względem $Ox$ zmienia się znak $y$, względem $Oy$ — znak $x$, względem początku układu — oba znaki.","Z równania odczytujemy środek: $(1, -2)$ i $r^2=5$.","Symetria względem początku układu zmienia znaki obu współrzędnych: nowy środek $(-1, 2)$. Promień się nie zmienia.","Równanie: $(x+1)^2+(y-2)^2=5$.","Odpowiedź: $(x+1)^2+(y-2)^2=5$."],"2608-26":["Pomysł: szukamy trójkąta prostokątnego, w którym leży szukana wielkość — zwykle tworzą go wysokość ostrosłupa, odcinek w podstawie (rzut krawędzi) i krawędź boczna.","Kąt nachylenia krawędzi bocznej do podstawy leży w trójkącie prostokątnym: krawędź boczna $12$ (przeciwprostokątna), wysokość $H$ (naprzeciw kąta) i połowa przekątnej podstawy.","Wysokość leży naprzeciw kąta, więc $\\sin60^\\circ=\\frac{H}{12}$, a stąd $H=12\\cdot\\sin60^\\circ=12\\cdot \\frac{\\sqrt3}{2}=6\\sqrt{3}$.","Odpowiedź: $6\\sqrt{3}$."],"2408-26":["Pomysł: w prostopadłościanie przekątną liczymy dwa razy z Pitagorasa: najpierw przekątna podstawy, potem przekątna bryły ($a\\sqrt2$ i $a\\sqrt3$ w sześcianie).","Krawędź $AB$ jest prostopadła do ściany $ADHE$, więc jest prostopadła do każdego odcinka w tej ścianie, także do $AH$. Trójkąt $ABH$ jest prostokątny (kąt prosty przy $A$).","W tym trójkącie: $BH$ — przeciwprostokątna, $AB=6$ — przyprostokątna naprzeciw kąta $30^\\circ$ (przy $H$). Więc $\\sin30^\\circ=\\frac{|AB|}{|BH|}$.","$|BH|=\\frac{6}{\\sin30^\\circ}=6:\\frac12=6\\cdot 2=12$.","Odpowiedź: $12$."],"2406-26":["Pomysł: w prostopadłościanie przekątną liczymy dwa razy z Pitagorasa: najpierw przekątna podstawy, potem przekątna bryły ($a\\sqrt2$ i $a\\sqrt3$ w sześcianie).","Ściana sześcianu to kwadrat o boku $a$, a jego przekątna ma długość $a\\sqrt2$.","$a\\sqrt2=2\\sqrt2$, więc krawędź $a=2$.","Objętość sześcianu: $V=a^3=2^3=8$.","Odpowiedź: $8$."],"2505-26":["Pomysł: w prostopadłościanie przekątną liczymy dwa razy z Pitagorasa: najpierw przekątna podstawy, potem przekątna bryły ($a\\sqrt2$ i $a\\sqrt3$ w sześcianie).","Objętość sześcianu to $a^3$: $a^3=729$, więc $a=\\sqrt[3]{729}=9$.","Przekątna sześcianu (z Pitagorasa dwa razy: $a\\sqrt2$, potem $\\sqrt{(a\\sqrt2)^2+a^2}$) ma długość $a\\sqrt3$.","$9\\sqrt3$.","Odpowiedź: $9\\sqrt{3}$."],"2305-25":["Pomysł: kąt nachylenia przekątnej bryły do podstawy widać w trójkącie prostokątnym: przekątna podstawy, krawędź boczna (wysokość) i przekątna bryły.","Kąt $\\alpha$ leży w trójkącie prostokątnym: przekątna podstawy $d$ (przy kącie), wysokość i przekątna bryły $D$ (przeciwprostokątna).","Podstawa to kwadrat o boku $15$: $d=15\\sqrt2$. Cosinus: $\\cos\\alpha=\\frac{d}{D}$, czyli $\\frac{\\sqrt2}{3}=\\frac{15\\sqrt2}{D}$.","Mnożymy na krzyż: $\\sqrt2\\cdot D=15\\sqrt2\\cdot 3$. Dzielimy przez $\\sqrt2$ (skraca się): $D=15\\cdot 3=45$.","Odpowiedź: $45$."],"2306-30":["Pomysł: kąt nachylenia przekątnej bryły do podstawy widać w trójkącie prostokątnym: przekątna podstawy, krawędź boczna (wysokość) i przekątna bryły.","$AD$ to najdłuższa przekątna sześciokąta foremnego — przechodzi przez środek i składa się z dwóch boków trójkątów równobocznych: $|AD|=2\\cdot 5=10$.","W trójkącie $ADD'$ kąt przy $A$ ma $45^\\circ$ i kąt przy $D$ jest prosty, więc trójkąt jest równoramienny: $H=|DD'|=|AD|=10$.","Ściana boczna to prostokąt $5\\times 10$: pole $5\\cdot 10=50$.","Odpowiedź: $50$."],"2406-27":["Pomysł: kąt nachylenia przekątnej bryły do podstawy widać w trójkącie prostokątnym: przekątna podstawy, krawędź boczna (wysokość) i przekątna bryły.","Kąt nachylenia przekątnej graniastosłupa do podstawy leży w trójkącie prostokątnym: przekątna podstawy $d$, wysokość $H$ i przekątna bryły.","Podstawa to kwadrat o boku $4$, więc $d=4\\sqrt2$.","Wysokość leży naprzeciw kąta, $d$ — przy kącie: $\\operatorname{tg}\\alpha=\\frac{H}{d}$, więc $H=2\\cdot 4\\sqrt2=8\\sqrt{2}$.","Odpowiedź: $8\\sqrt{2}$."],"2405-25.1":["Pomysł: z pola podstawy (sześciokąt = $6$ trójkątów równobocznych) wyznaczamy krawędź podstawy; ściana boczna to prostokąt: krawędź podstawy × wysokość.","Podstawa to sześciokąt foremny: $6$ trójkątów równobocznych, pole $\\frac{3a^2\\sqrt3}{2}$.","$\\frac{3a^2\\sqrt3}{2}=\\frac{30\\sqrt3}{2}$ — po obu stronach jest $\\frac{\\sqrt3}{2}$, więc $3a^2=30$.","Dzielimy przez $3$: $a^2=10$, więc $a=\\sqrt{10}$.","Ściana boczna to prostokąt o bokach $a$ i $H$: $\\sqrt{10}\\cdot 6=6\\sqrt{10}$.","Odpowiedź: $6\\sqrt{10}$."],"2405-26":["Pomysł: pole całkowite = pole podstawy + pole boczne. W bryłach podobnych w skali $k$ pola mnożą się przez $k^2$, a objętości przez $k^3$.","Objętości brył podobnych mają się jak sześcian skali: $k^3=\\frac{64}{8}=8$, więc $k=\\sqrt[3]{8}=2$.","Pola (także całkowite) mają się jak kwadrat skali: $k^2=2^2$.","Stosunek pól: $4$.","Odpowiedź: $4$."],"2506-26":["Pomysł: w stożku kluczowy jest trójkąt prostokątny: wysokość $H$, promień $r$ i tworząca $l$; kąt rozwarcia to podwojony kąt między wysokością a tworzącą.","Kąt rozwarcia to kąt między dwiema tworzącymi w przekroju osiowym; wysokość dzieli go na pół: $\\frac{60^\\circ}{2}=30^\\circ$.","W trójkącie prostokątnym (wysokość $H$, promień $r$, tworząca $6$) wysokość leży <b>przy</b> kącie $30^\\circ$, więc $\\cos30^\\circ=\\frac{H}{6}$, a stąd $H=6\\cdot\\cos30^\\circ=6\\cdot \\frac{\\sqrt3}{2}=3\\sqrt{3}$.","Odpowiedź: $3\\sqrt{3}$."],"2508-27":["Pomysł: w stożku kluczowy jest trójkąt prostokątny: wysokość $H$, promień $r$ i tworząca $l$; kąt rozwarcia to podwojony kąt między wysokością a tworzącą.","Objętość walca: $V=\\pi r^2h$.","$\\pi\\cdot 2^2\\cdot h=16\\pi^2$, czyli $4\\pi\\cdot h=16\\pi^2$.","Dzielimy przez $4\\pi$: $h=\\frac{16\\pi^2}{4\\pi}=4\\pi$.","Odpowiedź: $4\\pi$."],"2305-28":["Pomysł: liczymy, ile jest możliwości na każdym miejscu (od lewej, pamiętając, że pierwsza cyfra nie może być zerem), i mnożymy — to reguła mnożenia.","Liczba ma $5$ miejsc na cyfry, a do wyboru są $3$ cyfry: $0, 5, 7$ (mogą się powtarzać).","Na pierwszym miejscu nie może stać $0$ — zostaje $2$ możliwości; na każdym z pozostałych $4$ miejsc — $3$ możliwości.","Reguła mnożenia: $2\\cdot 3^{4}=162$.","Odpowiedź: $2\\cdot 3^{4}$."],"2508-28":["Pomysł: liczymy, ile jest możliwości na każdym miejscu (od lewej, pamiętając, że pierwsza cyfra nie może być zerem), i mnożymy — to reguła mnożenia.","Cyfry nieparzyste: $1, 3, 5, 7, 9$.","Liczba ma być większa od $500$: cyfra setek musi wynosić co najmniej $5$ i być nieparzysta — $5, 7, 9$ (3 możliwości).","Dziesiątki i jedności: po $5$ możliwości. Razem $3\\cdot5\\cdot5=75$.","Odpowiedź: $75$."],"2506-14.2":["Pomysł: najpewniej wypisać kilka pierwszych wyrazów i na nich sprawdzić każde stwierdzenie.","Najprościej wypisać kilka pierwszych wyrazów: $a_1=0$, $a_2=6$, $a_3=18$, $a_4=36$.","Kolejne wyrazy: $0, 6, 18, 36$; różnice $6, 12, 18$ nie są stałe.","$a_1=3\\cdot1-3\\cdot1=0$."],"2406-16.2":["Pomysł: najpewniej wypisać kilka pierwszych wyrazów i na nich sprawdzić każde stwierdzenie.","$(-1)^{n+1}$ to $1$ dla nieparzystych $n$ i $-1$ dla parzystych. Kolejne wyrazy: $7, 3, 7, 3,\\ldots$","Wyrazy na zmianę: $7, 3, 7, 3,\\ldots$ — raz maleją, raz rosną.","Różnice: $-4$, potem $4$ — nie są stałe."],"2312-20":["Pomysł: okrąg o środku $(a, b)$ i promieniu $r$ ma równanie $(x-a)^2+(y-b)^2=r^2$ — znaki w nawiasach są przeciwne do współrzędnych środka, a po prawej jest $r^2$.","Równanie okręgu o środku $(a, b)$ i promieniu $r$: $(x-a)^2+(y-b)^2=r^2$.","Środek: $(4, -2)$.","$r=2$, więc $r^2=2^2=4$.","Uwaga na znaki: $x-(4)$ to $x-4$, a $y-(-2)$ to $y+2$. Równanie: $(x-4)^2+(y+2)^2=4$.","Odpowiedź: $(x-4)^2+(y+2)^2=4$."],"2405-2":["Pomysł: wszystkie liczby zapisujemy jako potęgi tej samej podstawy (np. $8=2^3$, $\\frac1{16}=2^{-4}$). Potem przy mnożeniu dodajemy wykładniki, przy dzieleniu odejmujemy.","Zapisujemy liczby jako potęgi $2$: $16=2^{4}$, więc $\\frac1{16}=2^{-4}$; oraz $8=2^{3}$.","Potęga potęgi — wykładniki mnożymy: $\\left(2^{-4}\\right)^{8}=2^{-4\\cdot 8}=2^{-32}$ oraz $\\left(2^{3}\\right)^{16}=2^{3\\cdot 16}=2^{48}$.","Mnożenie potęg o tej samej podstawie — wykładniki dodajemy: $2^{-32}\\cdot 2^{48}=2^{-32+48}=2^{16}$.","Odpowiedź: $2^{16}$."],"2505-6":["Pomysł: opuszczamy nawias, przenosimy wyrazy z $x$ na jedną stronę i zaznaczamy wynik na osi.","Opuszczamy nawias (mnożymy przez $-2$): $3-2+4x\\geq 2x-17$, czyli $1+4x\\geq 2x-17$.","Wyrazy z $x$ na lewo, liczby na prawo: $4x-2x\\geq -17-1$, czyli $2x\\geq -18$.","Dzielimy przez $2$ (dodatnia — zwrot zostaje): $x\\geq -9$. Na osi: od $-9$ w prawo, kółko zamalowane."],"inf-8":["Pomysł: sprawdzamy znak wyrażenia pod wartością bezwzględną — dodatnie zostaje, ujemne zmienia znak.","$\\sqrt{5}>1$, więc $\\left|\\sqrt{5}-1\\right|=\\sqrt{5}-1$.","$\\sqrt{5}>2$ (bo $2^2=4<5$), więc $2-\\sqrt{5}<0$ i $\\left|2-\\sqrt{5}\\right|=\\sqrt{5}-2$.","$\\sqrt{5}-1-3(\\sqrt{5}-2)=\\sqrt{5}-1-3\\sqrt{5}+6=5-2\\sqrt{5}$.","Odpowiedź: $5-2\\sqrt{5}$."],"2412-7":["Pomysł: podstawiamy znane $x$ i $y$ do równań i wyznaczamy $a$ oraz $b$.","Podstawiamy do pierwszego równania: $a\\cdot (-1)+3\\cdot 6=20$, czyli $-a=20-18=2$, więc $a=-2$.","Do drugiego: $-1+b\\cdot 6=5$, czyli $6b=6$, więc $b=1$.","$a\\cdot b=\\left(-2\\right)\\cdot 1=-2$.","Odpowiedź: $\\left(-2\\right)$."],"2603-1":["Pomysł: dzielna = iloraz · dzielnik + reszta, a potem dzielimy obie strony przez dzielnik.","Dzielenie z resztą: dzielna = iloraz $\\cdot$ dzielnik + reszta, więc $x=20y+26$.","Dzielimy obie strony przez $y$: $\\frac{x}{y}=\\frac{20y+26}{y}=\\frac{20y}{y}+\\frac{26}{y}=20+\\frac{26}{y}$.","Odpowiedź: $20+\\frac{26}{y}$."],"2605-5":["Pomysł: rozkładamy na czynniki pierwsze i łączymy dwójki z piątkami w dziesiątki — liczba $10^n$ ma $n+1$ cyfr.","$4^{12}\\cdot 5^{24}=2^{24}\\cdot 5^{24}=10^{24}$ — dzieli się przez $20$.","$10^{24}$ to jedynka i $24$ zer — ma $25$ cyfr."],"2306-4":["Pomysł: przy rocznej kapitalizacji co roku kapitał mnożymy przez $1+\\frac{p}{100}$. Odsetki to różnica między kwotą końcową a wpłaconą.","Co roku kwota rośnie o $7\\%$, czyli mnożymy ją przez $1+\\frac{7}{100}=1{,}07$.","Po pierwszym roku: odsetki to $7\\%$ z $30\\,000$, czyli $\\frac{7}{100}\\cdot 30\\,000=2\\,100$ zł; na koncie $30\\,000+2\\,100=32\\,100$ zł.","Po drugim roku: odsetki liczone od nowej kwoty: $\\frac{7}{100}\\cdot 32\\,100=2247$ zł; na koncie $32\\,100+2247=34\\,347$ zł.","Łączne odsetki to przyrost: $34\\,347-30\\,000=4\\,347$ zł.","Odpowiedź: $4\\,347\\text{ zł}$."],"2312-3":["Pomysł: procent składany — kwota po dwóch latach to $K\\cdot q^2$; dzielimy, żeby znaleźć $K$.","Po każdym roku kwota rośnie o $5\\%$, czyli mnoży się przez $1{,}05$. Po dwóch latach: $K\\cdot 1{,}05\\cdot 1{,}05=K\\cdot 1{,}1025$.","$K\\cdot 1{,}1025=4\\,851$, więc $K=4\\,851:1{,}1025=4\\,400$ zł.","Sprawdzenie: $4\\,400\\cdot 1{,}1025=4\\,851$.","Odpowiedź: $4\\,400\\text{ zł}$."],"2605-2":["Pomysł: przy rocznej kapitalizacji co roku kapitał mnożymy przez $1+\\frac{p}{100}$. Odsetki to różnica między kwotą końcową a wpłaconą.","Co roku kwota rośnie o $6\\%$, czyli mnożymy ją przez $1+\\frac{6}{100}=1{,}06$.","Po pierwszym roku: odsetki to $6\\%$ z $10\\,000$, czyli $\\frac{6}{100}\\cdot 10\\,000=600$ zł; na koncie $10\\,000+600=10\\,600$ zł.","Po drugim roku: odsetki liczone od nowej kwoty: $\\frac{6}{100}\\cdot 10\\,600=636$ zł; na koncie $10\\,600+636=11\\,236$ zł.","Łączne odsetki to przyrost: $11\\,236-10\\,000=1\\,236$ zł.","Odpowiedź: $1\\,236\\text{ zł}$."],"inf-15":["Pomysł: rozpisujemy kwadrat różnicy pierwiastków i patrzymy, przy jakim $a$ znika część niewymierna.","$\\left(\\sqrt{3}-\\sqrt{2}\\right)^2=3-2\\sqrt{3}\\sqrt{2}+2=5-2\\sqrt{6}$.","Więc $x=a-(5-2\\sqrt{6})=a-5+2\\sqrt{6}$. Liczba $x$ jest wymierna, gdy $a$ „zjada” $2\\sqrt{6}$, czyli zawiera $-2\\sqrt{6}$.","$\\left(\\sqrt{2}-\\sqrt{3}\\right)^2=5-2\\sqrt{6}$ (to samo co wyżej), więc $a=\\left(\\sqrt{2}-\\sqrt{3}\\right)^2+0{,}3$ daje $x=0{,}3$; a $a=-2\\sqrt{6}+12{,}5$ daje $x=12{,}5-5=7{,}5$ — obie wymierne."],"2505-7":["Pomysł: iloczyn jest zerem, gdy któryś czynnik jest zerem; $x^2+c$ z $c>0$ nigdy nie jest zerem.","Iloczyn jest zerem, gdy któryś czynnik jest zerem: $2x=0\\Rightarrow x=0$; $x+3=0\\Rightarrow x=-3$.","$x^2+25=0$ — kwadrat liczby plus liczba dodatnia nigdy nie jest zerem, brak rozwiązań.","Rozwiązania: $-3$ i $0$ — dokładnie dwa.","Odpowiedź: $\\text{dwa rozwiązania: }(-3)\\text{ oraz }0\\text{.}$"],"2506-7":["Pomysł: każdy czynnik przyrównujemy do zera i liczymy <b>różne</b> rozwiązania.","$(x-1)^2=0\\Rightarrow x=1$ (jedno rozwiązanie).","$x^2-25=0\\Rightarrow x^2=25\\Rightarrow x=5$ lub $x=-5$.","Rozwiązania: $1$, $5$, $-5$ — trzy różne.","Odpowiedź: $\\text{trzy rozwiązania.}$"],"2603-7":["Pomysł: każdy czynnik osobno; dla trójmianu sprawdzamy $\\Delta$.","$2x=0\\Rightarrow x=0$; $x^2-3=0\\Rightarrow x=\\sqrt{3}$ lub $x=-\\sqrt{3}$.","$x^2+2x+3=0$: $\\Delta=2^2-4\\cdot 3=4-12=-8<0$ — brak rozwiązań.","Razem trzy rozwiązania: $0$, $\\sqrt{3}$, $-\\sqrt{3}$.","Odpowiedź: $\\text{trzy rozwiązania.}$"],"2209-7":["Pomysł: najpierw dziedzina (mianownik ≠ 0), potem zera licznika — odrzucamy te spoza dziedziny.","Dziedzina: $x^2-1\\neq 0$, czyli $x\\neq 1$ i $x\\neq -1$.","Licznik: $x^2+x=x(x+1)$, więc zeruje się dla $x=0$, $x=-1$, $x=-3$, $x=1$.","Odrzucamy $\\pm 1$ (poza dziedziną). Zostają $x=-3$ i $x=0$ — dwa rozwiązania.","Odpowiedź: $\\text{dwa rozwiązania: }x=-3, x=0\\text{.}$"],"2405-7":["Pomysł: ułamek jest równy zero, gdy licznik jest zerem, a mianownik nie. Zaczynamy od dziedziny — liczby zerujące mianownik odpadają.","Ułamek jest równy zero, gdy licznik jest równy zero, a mianownik nie.","Dziedzina: mianownik nie może być zerem, więc $x\\neq-2$ i $x\\neq3$.","Licznik: $x+1=0\\Rightarrow x=-1$ — ta liczba należy do dziedziny, więc jest rozwiązaniem.","Odpowiedź: $\\text{ma dokładnie jedno rozwiązanie: }\\left(-1\\right)\\text{.}$"],"2408-6":["Pomysł: najpierw dziedzina (mianownik ≠ 0), potem zera licznika — odrzucamy te spoza dziedziny.","Dziedzina: $2x+4\\neq 0$, czyli $x\\neq -2$.","Licznik zeruje się dla $x=0$, $x=-5$ oraz $x=2$ (bo $2-x=0$).","Żadna z tych liczb nie jest równa $-2$, więc są trzy rozwiązania: $-5$, $0$, $2$.","Odpowiedź: $\\text{trzy rozwiązania: }(-5), 0\\text{ oraz }2\\text{.}$"],"2312-6":["Pomysł: podstawiamy pary do obu równań — rozwiązanie spełnia oba.","Najszybciej: podstawiamy każdą parę do obu równań. Para jest rozwiązaniem, gdy spełnia oba.","Dla $x=-2$, $y=1$: $\\cdot (-2)-3\\cdot 1+5=0$ ✓ oraz $2\\cdot (-2)+1+3=0$ ✓.","Odpowiedź: $x=-2\\text{ i }y=1$."],"inf-21":["Pomysł: porównujemy równania — jeśli jedno jest wielokrotnością drugiego po lewej stronie, ale nie po prawej, proste są równoległe i układ nie ma rozwiązań; jeśli w całości — rozwiązań jest nieskończenie wiele.","Każde równanie układu opisuje prostą; rozwiązanie układu to punkt wspólny obu prostych.","Porównujemy współczynniki: czy lewa strona drugiego równania jest wielokrotnością lewej strony pierwszego (te same proporcje przy $x$ i przy $y$)?","Tak — i prawa strona też: drugie równanie to pierwsze pomnożone przez $-4$. To ta sama prosta, więc rozwiązań jest nieskończenie wiele.","Odpowiedź: $\\text{ma nieskończenie wiele rozwiązań.}$"],"2606-13.1":["Pomysł: parabola jest symetryczna względem prostej $x=p$. Punkty o tej samej wartości (np. dwa miejsca zerowe) leżą w równych odległościach od $p$, więc $p$ jest ich średnią.","Parabola jest symetryczna względem pionowej prostej przez wierzchołek: $x=-3$.","Dwa różne argumenty o tej samej wartości leżą w tej samej odległości od $-3$, więc $-3$ jest ich średnią: $\\frac{-9+t}{2}=-3$.","Mnożymy obie strony przez $2$: $-9+t=-6$, więc $t=-6-(-9)=3$.","Odpowiedź: $3$."],"2608-22.1":["Pomysł: współczynnik kierunkowy to „o ile w górę na jeden krok w prawo”: $a=\\frac{y_B-y_A}{x_B-x_A}$. Potem $b$ z podstawienia jednego z punktów.","Współczynnik kierunkowy: $a=\\frac{y_B-y_A}{x_B-x_A}=\\frac{2-(-6)}{4-0}=\\frac{8}{4}=2$.","Wyraz wolny z punktu $A$: $-6=2\\cdot 0+b$, czyli $b=-6-0=-6$.","Prosta: $y=2x-6$.","Odpowiedź: $y=2x-6$."],"2312-8":["Pomysł: jeśli $W(x)=(x+1)Q(x)$, to $W(-1)=0$.","Skoro $W(x)=(x+1)\\cdot Q(x)$, to $W(-1)=0$ (czynnik $x+1$ się zeruje).","$W(-1)=-3\\cdot(-1)^3+(-1)\\cdot(-1)^2+k\\cdot(-1)+1=3-1-k+1=3-k$.","$3-k=0$, więc $k=3$.","Odpowiedź: $3$."]};
